-- V409: additive sharing metadata. Legacy table ACLs intentionally remain unchanged.
ALTER TABLE public.auto_account_contact_groups
  ADD COLUMN sharing_scope text NOT NULL DEFAULT 'private'
    CHECK (sharing_scope IN ('private','organization','selected')),
  ADD COLUMN sharing_revision bigint NOT NULL DEFAULT 0;
ALTER TABLE public.auto_content_groups
  ADD COLUMN sharing_scope text NOT NULL DEFAULT 'private'
    CHECK (sharing_scope IN ('private','organization','selected')),
  ADD COLUMN sharing_revision bigint NOT NULL DEFAULT 0;

CREATE TABLE public.auto_data_group_recipients (
  group_id bigint NOT NULL REFERENCES public.auto_account_contact_groups(id) ON DELETE CASCADE,
  staff_id bigint NOT NULL REFERENCES public.org_staff(id) ON DELETE CASCADE,
  PRIMARY KEY (group_id, staff_id)
);
CREATE INDEX auto_data_group_recipients_staff ON public.auto_data_group_recipients(staff_id,group_id);
CREATE TABLE public.auto_content_group_recipients (
  group_id bigint NOT NULL REFERENCES public.auto_content_groups(id) ON DELETE CASCADE,
  staff_id bigint NOT NULL REFERENCES public.org_staff(id) ON DELETE CASCADE,
  PRIMARY KEY (group_id, staff_id)
);
CREATE INDEX auto_content_group_recipients_staff ON public.auto_content_group_recipients(staff_id,group_id);
ALTER TABLE public.auto_data_group_recipients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.auto_content_group_recipients ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.auto_data_group_recipients,public.auto_content_group_recipients FROM PUBLIC,anon,authenticated,service_role;

CREATE TABLE private.group_copy_requests (
  staff_id bigint NOT NULL REFERENCES public.org_staff(id) ON DELETE CASCADE,
  organization_id bigint NOT NULL REFERENCES public.org_organization(id) ON DELETE CASCADE,
  request_id text NOT NULL CHECK (length(request_id) BETWEEN 1 AND 500),
  request_hash text NOT NULL,
  result jsonb,
  PRIMARY KEY (staff_id,organization_id,request_id)
);
ALTER TABLE private.group_copy_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.group_copy_requests FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private.group_access(p_kind text,p_group_id bigint,p_staff_id bigint,p_organization_id bigint)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
  WITH resource AS (
    SELECT id,staff_id,organization_id,sharing_scope,sharing_revision
    FROM public.auto_account_contact_groups
    WHERE p_kind='data' AND id=p_group_id AND purpose='data_group' AND NOT is_delete
    UNION ALL
    SELECT id,staff_id,organization_id,sharing_scope,sharing_revision
    FROM public.auto_content_groups
    WHERE p_kind='content' AND id=p_group_id AND NOT is_delete
  )
  SELECT jsonb_build_object(
    'ownerStaffId',g.staff_id,'ownerName',COALESCE(NULLIF(owner.name,''),'Nhân viên #'||owner.id),
    'role',CASE WHEN g.staff_id=p_staff_id THEN 'owner' ELSE 'shared' END,
    'canManage',g.staff_id=p_staff_id,'canUse',true,'canCopy',true,
    'scope',g.sharing_scope,'revision',g.sharing_revision::text)
  FROM resource g
  JOIN public.org_staff owner ON owner.id=g.staff_id AND owner.organization_id=g.organization_id
    AND owner.deleted_at IS NULL AND owner.is_active
  JOIN public.org_staff viewer ON viewer.id=p_staff_id AND viewer.organization_id=g.organization_id
    AND viewer.deleted_at IS NULL AND viewer.is_active
  WHERE g.organization_id=p_organization_id AND (
    g.staff_id=p_staff_id OR g.sharing_scope='organization' OR
    (g.sharing_scope='selected' AND (
      (p_kind='data' AND EXISTS(SELECT 1 FROM public.auto_data_group_recipients r WHERE r.group_id=g.id AND r.staff_id=p_staff_id))
      OR (p_kind='content' AND EXISTS(SELECT 1 FROM public.auto_content_group_recipients r WHERE r.group_id=g.id AND r.staff_id=p_staff_id))
    ))
  );
$fn$;
REVOKE ALL ON FUNCTION private.group_access(text,bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private.can_read_data_group(p_group_id bigint,p_staff_id bigint,p_organization_id bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
  SELECT private.group_access('data',p_group_id,p_staff_id,p_organization_id) IS NOT NULL;
$fn$;
REVOKE ALL ON FUNCTION private.can_read_data_group(bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Group row is the established lock root for intake, bind, snapshot and revoke.
CREATE FUNCTION private.lock_read_data_group(p_group_id bigint,p_staff_id bigint,p_organization_id bigint)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
BEGIN
  PERFORM id FROM public.auto_account_contact_groups WHERE id=p_group_id FOR SHARE;
  RETURN private.can_read_data_group(p_group_id,p_staff_id,p_organization_id);
END;
$fn$;
REVOKE ALL ON FUNCTION private.lock_read_data_group(bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION private.shared_data_member_owner(p_group_id bigint,p_contact_staff_id bigint,p_staff_id bigint,p_organization_id bigint)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
  SELECT EXISTS(SELECT 1 FROM public.auto_account_contact_groups g
    WHERE g.id=p_group_id AND g.staff_id=p_contact_staff_id
      AND private.can_read_data_group(g.id,p_staff_id,p_organization_id));
$fn$;
REVOKE ALL ON FUNCTION private.shared_data_member_owner(bigint,bigint,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Membership changes revoke active cross-staff subscriptions immediately. Rejoining
-- never reactivates a source; the recipient must explicitly bind/reactivate again.
CREATE FUNCTION private.stop_invalid_staff_group_sources() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE v_group bigint; v_source record;
BEGIN
  IF NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
    AND NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at
    AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active THEN RETURN NEW; END IF;
  FOR v_group IN SELECT DISTINCT g.id FROM public.auto_account_contact_groups g
    JOIN public.auto_campaign_data_group_sources s ON s.group_id=g.id
    WHERE s.staff_id<>g.staff_id AND (g.staff_id=NEW.id OR s.staff_id=NEW.id)
      AND s.status IN ('active','baselining') ORDER BY g.id
  LOOP
    PERFORM id FROM public.auto_account_contact_groups WHERE id=v_group FOR UPDATE;
    FOR v_source IN SELECT s.id,s.campaign_id FROM public.auto_campaign_data_group_sources s
      JOIN public.auto_account_contact_groups g ON g.id=s.group_id
      WHERE s.group_id=v_group AND s.staff_id<>g.staff_id AND s.status IN ('active','baselining')
        AND NOT private.can_read_data_group(g.id,s.staff_id,s.organization_id)
      ORDER BY s.campaign_id,s.id
    LOOP
      PERFORM public.aka_agent_lock_campaign_input_serialization(v_source.campaign_id);
      UPDATE public.auto_campaign_data_group_sources SET status='stopped',stop_reason='sharing_revoked',stopped_at=now(),updated_at=now()
        WHERE id=v_source.id AND status IN ('active','baselining');
    END LOOP;
  END LOOP;
  RETURN NEW;
END;
$fn$;
REVOKE ALL ON FUNCTION private.stop_invalid_staff_group_sources() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER group_sharing_staff_scope_changed
AFTER UPDATE OF organization_id,deleted_at,is_active ON public.org_staff
FOR EACH ROW EXECUTE FUNCTION private.stop_invalid_staff_group_sources();


CREATE OR REPLACE FUNCTION private.list_shared_data_groups(p_staff_id bigint, p_organization_id bigint, p_search text, p_compatible_action_id text, p_compatible_data_type_category_item_id bigint, p_data_type_category_item_ids bigint[], p_offset integer, p_limit integer, p_unrestricted_only boolean, p_owned_only boolean)
 RETURNS TABLE(id bigint, name text, color text, sort_order integer, revision bigint, data_type_category_item_id bigint, data_type_code text, data_type_name text, dataset_sync_mode text, active_membership_count bigint, is_delete boolean, staff_id bigint, organization_id bigint, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF COALESCE(p_offset, 0) < 0
    OR COALESCE(p_limit, 100) NOT BETWEEN 1 AND 500
  THEN
    RAISE EXCEPTION 'invalid_data_group_page';
  END IF;
  IF p_compatible_data_type_category_item_id IS NOT NULL
    AND NOT public.aka_agent_is_data_type_category_item(
      p_compatible_data_type_category_item_id, true
    )
  THEN
    RAISE EXCEPTION 'invalid_data_type_category_item';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT contact_group.*
    FROM public.auto_account_contact_groups AS contact_group
    WHERE (NOT p_owned_only OR contact_group.staff_id = p_staff_id)
      AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
      AND contact_group.organization_id = p_organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false
      AND (
        NULLIF(btrim(COALESCE(p_search, '')), '') IS NULL
        OR contact_group.name ILIKE '%' || btrim(p_search) || '%'
      )
      AND (
        p_data_type_category_item_ids IS NULL
        OR contact_group.data_type_category_item_id =
          ANY(p_data_type_category_item_ids)
      )
      AND (
        NOT COALESCE(p_unrestricted_only, false)
        OR contact_group.data_type_category_item_id IS NULL
      )
      AND (
        p_compatible_data_type_category_item_id IS NULL
        OR contact_group.data_type_category_item_id IS NULL
        OR contact_group.data_type_category_item_id =
          p_compatible_data_type_category_item_id
      )
      AND (
        NULLIF(btrim(COALESCE(p_compatible_action_id, '')), '') IS NULL
        OR contact_group.data_type_category_item_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.auto_campaign_action_data_types AS mapping
          WHERE mapping.campaign_action_id =
              btrim(p_compatible_action_id)
            AND mapping.data_type_category_item_id =
              contact_group.data_type_category_item_id
            AND mapping.can_target = true
            AND mapping.is_active = true
            AND mapping.is_delete = false
        )
      )
  )
  SELECT
    filtered.id,
    filtered.name,
    filtered.color,
    filtered.sort_order,
    filtered.revision,
    filtered.data_type_category_item_id,
    data_type_item.code,
    data_type_item.name,
    filtered.dataset_sync_mode,
    (
      SELECT count(*)
      FROM public.auto_account_contact_group_members AS member
      WHERE member.group_id = filtered.id
        AND member.is_delete = false
    )::bigint,
    filtered.is_delete,
    filtered.staff_id,
    filtered.organization_id,
    filtered.created_at,
    filtered.updated_at,
    count(*) OVER ()::bigint
  FROM filtered
  LEFT JOIN public.category_item AS data_type_item
    ON data_type_item.id = filtered.data_type_category_item_id
  ORDER BY
    filtered.sort_order,
    filtered.updated_at DESC,
    filtered.id DESC
  OFFSET COALESCE(p_offset, 0)
  LIMIT COALESCE(p_limit, 100);
END;
$function$;

REVOKE ALL ON FUNCTION private.list_shared_data_groups(bigint,bigint,text,text,bigint,bigint[],integer,integer,boolean,boolean) FROM PUBLIC,anon,authenticated,service_role;


CREATE OR REPLACE FUNCTION private.read_shared_group_members(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_search text, p_account_ids bigint[], p_include_accountless boolean, p_contact_types text[], p_flatform_types text[], p_status text, p_dataset_ids bigint[], p_data_type_category_item_ids bigint[], p_ids bigint[], p_exclude_ids bigint[], p_offset integer, p_limit integer)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
BEGIN
  RETURN QUERY SELECT to_jsonb(m) || jsonb_build_object('zalo_name',CASE WHEN contact.flatform_type='zalo' THEN COALESCE(NULLIF(u.zalo_name,''),NULLIF(z.zalo_name,''),contact.name) END,'display_name',CASE WHEN contact.flatform_type='zalo' THEN COALESCE(NULLIF(u.display_name,''),NULLIF(u.zalo_name,''),NULLIF(z.display_name,''),NULLIF(z.zalo_name,''),contact.name) END,'zalo_friend_status',CASE WHEN contact.flatform_type='zalo' AND contact.contact_type='person' THEN
        CASE WHEN u.id IS NOT NULL THEN CASE WHEN status.code IN ('friend','request_sent','request_received') THEN status.code ELSE 'stranger' END
          WHEN contact.is_friend IS TRUE THEN 'friend'
          WHEN COALESCE(contact.extra_data->>'friendRequestReceived',contact.extra_data->>'friend_request_received','false')='true' THEN 'request_received'
          WHEN COALESCE(contact.extra_data->>'friendRequestSent',contact.extra_data->>'friend_request_sent','false')='true' THEN 'request_sent'
          ELSE 'stranger' END END)
  FROM public.aka_agent_list_data_group_members(p_staff_id,p_organization_id,p_group_id,p_search,p_account_ids,p_include_accountless,p_contact_types,p_flatform_types,p_status,p_dataset_ids,p_data_type_category_item_ids,p_ids,p_exclude_ids,p_offset,p_limit) m
  JOIN public.auto_account_contacts contact ON contact.id=m.contact_id
  LEFT JOIN public.zalo_users z ON z.account_id=contact.account_id AND z.zalo_uid=contact.uid
      AND z.staff_id=contact.staff_id AND z.organization_id=contact.organization_id AND contact.flatform_type='zalo'
    LEFT JOIN public.chat_zalo_account_organization b ON b.auto_account_id=contact.account_id
      AND b.organization_id=contact.organization_id AND b.is_active AND contact.flatform_type='zalo'
    LEFT JOIN public.chat_zalo_account_user u ON u.chat_zalo_account_id=b.chat_zalo_account_id
      AND u.zalo_id=contact.uid AND contact.contact_type='person'
    LEFT JOIN public.category_item status ON status.id=u.friendship_status_category_item_id
  ORDER BY m.created_at DESC,m.id DESC;
END;
$function$;

REVOKE ALL ON FUNCTION private.read_shared_group_members(bigint,bigint,bigint,text,bigint[],boolean,text[],text[],text,bigint[],bigint[],bigint[],bigint[],integer,integer) FROM PUBLIC,anon,authenticated,service_role;


CREATE OR REPLACE FUNCTION public.aka_agent_bind_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_campaign_id bigint, p_group_id bigint, p_bundle_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_bundle public.auto_campaign_creation_bundles%ROWTYPE;
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_bundle_source record;
  v_request_hash text;
  v_rebinding boolean := false;
  v_source_found boolean := false;
  v_snapshot jsonb;
  v_campaign_count integer := 0;
  v_child_index_count integer := 0;
  v_min_child_index integer;
  v_max_child_index integer;
  v_invalid_campaign_count integer := 0;
  v_registered_count integer := 0;
  v_distinct_group_count integer := 0;
  v_invalid_source_count integer := 0;
  v_active_membership_count integer := 0;
  v_serialized_campaign_id bigint;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_data_group_bind_request';
  END IF;

  -- Common lock root for bind, ingest, delete and stop.
  SELECT contact_group.*
  INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;

  IF p_bundle_id IS NOT NULL THEN
    SELECT bundle.*
    INTO v_bundle
    FROM public.auto_campaign_creation_bundles AS bundle
    WHERE bundle.id = p_bundle_id
      AND bundle.staff_id = p_staff_id
      AND bundle.organization_id = p_organization_id
    FOR UPDATE;
    IF NOT FOUND OR v_bundle.status = 'failed' THEN
      RAISE EXCEPTION 'campaign_creation_bundle_not_found';
    END IF;

    IF v_bundle.data_group_id IS NULL THEN
      UPDATE public.auto_campaign_creation_bundles AS bundle
      SET data_group_id = v_group.id,
          updated_at = now()
      WHERE bundle.id = v_bundle.id
      RETURNING bundle.* INTO v_bundle;
    ELSIF v_bundle.data_group_id IS DISTINCT FROM v_group.id THEN
      RAISE EXCEPTION 'campaign_creation_bundle_group_mismatch';
    END IF;

    FOR v_serialized_campaign_id IN
      SELECT campaign.id
      FROM public.auto_campaigns AS campaign
      WHERE campaign.creation_bundle_id = p_bundle_id
      ORDER BY campaign.id
    LOOP
      PERFORM public.aka_agent_lock_campaign_input_serialization(
        v_serialized_campaign_id
      );
    END LOOP;

    -- The bundle lock prevents new FK references while every existing child
    -- and source is locked in one deterministic order.
    PERFORM campaign.id
    FROM public.auto_campaigns AS campaign
    WHERE campaign.creation_bundle_id = p_bundle_id
    ORDER BY campaign.creation_bundle_child_index NULLS LAST, campaign.id
    FOR UPDATE OF campaign;

    -- Binding the last child activates the whole bundle, so ownership of every
    -- child account is locked and revalidated rather than only the requested
    -- child. The bundle row above prevents a new child from joining this set.
    PERFORM account.id
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_accounts AS account ON account.id = campaign.account_id
    WHERE campaign.creation_bundle_id = p_bundle_id
    ORDER BY account.id
    FOR UPDATE OF account;

    IF EXISTS (
      SELECT 1
      FROM public.auto_campaigns AS campaign
      LEFT JOIN public.auto_accounts AS account ON account.id = campaign.account_id
      WHERE campaign.creation_bundle_id = p_bundle_id
        AND (
          account.id IS NULL
          OR account.staff_id IS DISTINCT FROM p_staff_id
          OR NOT (
            account.organization_id IS NULL
            OR account.organization_id = p_organization_id
          )
          OR COALESCE(account.is_delete, false)
          OR NOT (
            COALESCE(account.flatform_type, '') <> 'zalo'
            OR (
              account.organization_id = p_organization_id
              AND (
                (
                  v_runtime_target = 'desktop'
                  AND COALESCE(account.is_zalo_server, false) = false
                )
                OR (
                  v_runtime_target = 'server'
                  AND COALESCE(account.is_zalo_show_web, false) = false
                  AND COALESCE(account.is_zalo_server, false) = true
                  AND COALESCE(account.is_active, true) = true
                )
              )
            )
          )
        )
    ) THEN
      RAISE EXCEPTION 'data_group_campaign_account_not_found';
    END IF;

    SELECT campaign.*
    INTO v_campaign
    FROM public.auto_campaigns AS campaign
    WHERE campaign.id = p_campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.organization_id = p_organization_id;

    PERFORM source.id
    FROM public.auto_campaign_data_group_sources AS source
    WHERE source.bundle_id = p_bundle_id
    ORDER BY source.campaign_id, source.id
    FOR UPDATE OF source;
  ELSE
    PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

    SELECT campaign.*
    INTO v_campaign
    FROM public.auto_campaigns AS campaign
    WHERE campaign.id = p_campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.organization_id = p_organization_id
    FOR UPDATE;
  END IF;

  IF p_bundle_id IS NULL AND v_campaign.id IS NOT NULL THEN
    PERFORM account.id
    FROM public.auto_accounts AS account
    WHERE account.id = v_campaign.account_id
      AND account.staff_id = p_staff_id
      AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
      AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
    FOR UPDATE OF account;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'data_group_campaign_account_not_found';
    END IF;
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'bind_source',
    'campaignId', p_campaign_id,
    'groupId', p_group_id,
    'bundleId', p_bundle_id
  )::text);

  -- A committed bundle response is authoritative even if the campaign has
  -- subsequently started. This keeps retries stable across lifecycle changes.
  IF p_bundle_id IS NOT NULL THEN
    SELECT batch.*
    INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF FOUND THEN
      IF v_batch.operation <> 'bind_source'
        OR v_batch.group_id IS DISTINCT FROM p_group_id
        OR v_batch.request_hash <> v_request_hash
      THEN
        RAISE EXCEPTION 'data_group_request_id_conflict';
      END IF;
      IF v_batch.result IS NOT NULL THEN
        RETURN v_batch.result;
      END IF;
      RAISE EXCEPTION 'data_group_request_incomplete';
    END IF;
  END IF;

  IF v_campaign.id IS NULL OR COALESCE(v_campaign.is_delete, false) THEN
    RAISE EXCEPTION 'data_group_campaign_not_found';
  END IF;
  IF v_campaign.status IN ('đang chạy', 'hoàn thành')
    OR (
      v_campaign.schedule_end_date IS NOT NULL
      AND v_campaign.schedule_end_date <= now()
    )
  THEN
    RAISE EXCEPTION 'data_group_campaign_not_bindable';
  END IF;
  IF v_campaign.action_id NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    RAISE EXCEPTION 'data_group_campaign_action_incompatible';
  END IF;
  IF p_bundle_id IS NOT NULL THEN
    IF v_campaign.creation_bundle_id IS DISTINCT FROM p_bundle_id
      OR v_campaign.creation_bundle_child_index IS NULL
      OR v_campaign.creation_bundle_child_index < 0
      OR v_campaign.creation_bundle_child_index >= v_bundle.expected_campaign_count
    THEN
      RAISE EXCEPTION 'campaign_creation_bundle_child_invalid';
    END IF;
  ELSIF v_campaign.creation_bundle_id IS NOT NULL THEN
    RAISE EXCEPTION 'campaign_creation_bundle_required';
  END IF;

  SELECT source.*
  INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = v_campaign.id
  FOR UPDATE;
  v_source_found := FOUND;

  IF v_source_found THEN
    IF v_source.bundle_id IS DISTINCT FROM p_bundle_id THEN
      RAISE EXCEPTION 'campaign_data_group_source_immutable';
    END IF;
    IF v_source.group_id IS DISTINCT FROM v_group.id THEN
      IF p_bundle_id IS NOT NULL THEN
        RAISE EXCEPTION 'campaign_creation_bundle_group_mismatch';
      END IF;
      IF EXISTS (
        SELECT 1
        FROM public.auto_campaign_input_data AS input_data
        WHERE input_data.campaign_id = v_campaign.id
          AND input_data.canonical_target_key IS NOT NULL
          AND COALESCE(input_data.is_delete, false) = false
      ) THEN
        RAISE EXCEPTION 'campaign_data_group_source_immutable_after_intake';
      END IF;
      v_rebinding := true;
    ELSIF v_source.status = 'stopped' THEN
      RAISE EXCEPTION 'campaign_data_group_source_stopped_use_reactivate';
    ELSIF p_bundle_id IS NULL AND v_source.status = 'active' THEN
      -- Preserve the established non-bundle idempotent response.
      RETURN to_jsonb(v_source);
    END IF;
  END IF;

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status,
    staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'bind_source', p_group_id, v_request_hash,
    'processing', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT batch.*
    INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'bind_source'
      OR v_batch.group_id IS DISTINCT FROM p_group_id
      OR v_batch.request_hash <> v_request_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN
      RETURN v_batch.result;
    END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  -- A fresh request against an already committed ready bundle is harmless and
  -- gets its own completed idempotency row without replaying the snapshot.
  IF p_bundle_id IS NOT NULL AND v_bundle.status = 'ready' THEN
    IF NOT v_source_found
      OR v_source.status <> 'active'
      OR v_source.group_id IS DISTINCT FROM v_bundle.data_group_id
      OR v_source.baseline_revision IS DISTINCT FROM v_bundle.baseline_revision
    THEN
      RAISE EXCEPTION 'campaign_creation_bundle_ready_state_invalid';
    END IF;

    UPDATE public.auto_data_ingest_batches
    SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
    WHERE id = v_batch.id;
    RETURN to_jsonb(v_source);
  END IF;

  UPDATE public.auto_campaigns AS campaign
  SET data_target_source_mode = 'data_group',
      data_group_id = v_group.id,
      provisioning_state = 'staged',
      updated_at = now()
  WHERE campaign.id = v_campaign.id;

  IF NOT v_source_found THEN
    INSERT INTO public.auto_campaign_data_group_sources (
      campaign_id, group_id, bundle_id, baseline_revision, status,
      staff_id, organization_id
    ) VALUES (
      v_campaign.id, v_group.id, p_bundle_id,
      CASE WHEN p_bundle_id IS NULL THEN v_group.revision ELSE 0 END,
      'baselining',
      p_staff_id, p_organization_id
    )
    RETURNING * INTO v_source;
    v_source_found := true;
  ELSIF v_rebinding THEN
    -- The non-bundle path keeps v186's atomic empty-source rebind behavior.
    DELETE FROM public.auto_campaign_input_target_aliases AS alias
    WHERE alias.campaign_id = v_campaign.id
      AND NOT EXISTS (
        SELECT 1
        FROM public.auto_campaign_input_data AS input_data
        WHERE input_data.id = alias.input_data_id
          AND COALESCE(input_data.is_delete, false) = false
      );

    UPDATE public.auto_campaign_data_group_sources AS source
    SET group_id = v_group.id,
        baseline_revision = v_group.revision,
        status = 'baselining',
        started_at = NULL,
        stopped_at = NULL,
        stop_reason = NULL,
        last_ingest_at = NULL,
        updated_at = now()
    WHERE source.id = v_source.id
    RETURNING source.* INTO v_source;
  END IF;

  IF p_bundle_id IS NULL THEN
    -- Non-bundle behavior remains the established one-campaign transaction.
    v_snapshot := public.aka_agent_internal_route_group_snapshot(
      v_source.id, v_batch.id, v_group.revision
    );

    UPDATE public.auto_campaign_data_group_sources AS source
    SET status = 'active',
        baseline_revision = v_group.revision,
        started_at = COALESCE(source.started_at, now()),
        stopped_at = NULL,
        stop_reason = NULL,
        last_ingest_at = now(),
        updated_at = now()
    WHERE source.id = v_source.id
    RETURNING source.* INTO v_source;

    UPDATE public.auto_campaigns AS campaign
    SET provisioning_state = 'ready',
        note = CASE
          WHEN COALESCE((v_snapshot ->> 'inserted_input_count')::integer, 0)
             + COALESCE((v_snapshot ->> 'already_seen_input_count')::integer, 0) = 0
            THEN 'Chờ data phù hợp'
          WHEN campaign.note IN ('Chờ data phù hợp', 'Chờ data mới') THEN NULL
          ELSE campaign.note
        END,
        updated_at = now()
    WHERE campaign.id = v_campaign.id;

    UPDATE public.auto_data_ingest_batches
    SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
    WHERE id = v_batch.id;
    RETURN to_jsonb(v_source);
  END IF;

  SELECT
    count(*)::integer,
    count(DISTINCT campaign.creation_bundle_child_index)::integer,
    min(campaign.creation_bundle_child_index),
    max(campaign.creation_bundle_child_index),
    count(*) FILTER (WHERE
      campaign.staff_id IS DISTINCT FROM p_staff_id
      OR campaign.organization_id IS DISTINCT FROM p_organization_id
      OR COALESCE(campaign.is_delete, false)
      OR campaign.creation_bundle_child_index IS NULL
      OR campaign.creation_bundle_child_index < 0
      OR campaign.creation_bundle_child_index >= v_bundle.expected_campaign_count
    )::integer
  INTO
    v_campaign_count,
    v_child_index_count,
    v_min_child_index,
    v_max_child_index,
    v_invalid_campaign_count
  FROM public.auto_campaigns AS campaign
  WHERE campaign.creation_bundle_id = p_bundle_id;

  SELECT
    count(*)::integer,
    count(DISTINCT source.group_id)::integer,
    count(*) FILTER (WHERE
      source.staff_id IS DISTINCT FROM p_staff_id
      OR source.organization_id IS DISTINCT FROM p_organization_id
      OR source.group_id IS DISTINCT FROM v_group.id
      OR source.status <> 'baselining'
      OR campaign.id IS NULL
      OR campaign.creation_bundle_id IS DISTINCT FROM p_bundle_id
      OR campaign.staff_id IS DISTINCT FROM p_staff_id
      OR campaign.organization_id IS DISTINCT FROM p_organization_id
      OR COALESCE(campaign.is_delete, false)
      OR campaign.data_target_source_mode <> 'data_group'
      OR campaign.data_group_id IS DISTINCT FROM v_group.id
      OR campaign.provisioning_state <> 'staged'
    )::integer
  INTO
    v_registered_count,
    v_distinct_group_count,
    v_invalid_source_count
  FROM public.auto_campaign_data_group_sources AS source
  LEFT JOIN public.auto_campaigns AS campaign ON campaign.id = source.campaign_id
  WHERE source.bundle_id = p_bundle_id;

  IF v_registered_count < v_bundle.expected_campaign_count THEN
    IF v_invalid_source_count <> 0 OR v_distinct_group_count > 1 THEN
      RAISE EXCEPTION 'campaign_creation_bundle_registration_invalid';
    END IF;

    UPDATE public.auto_campaign_creation_bundles AS bundle
    SET ready_campaign_count = 0,
        status = 'staged',
        baseline_revision = NULL,
        updated_at = now()
    WHERE bundle.id = p_bundle_id
    RETURNING bundle.* INTO v_bundle;

    UPDATE public.auto_data_ingest_batches
    SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
    WHERE id = v_batch.id;
    RETURN to_jsonb(v_source);
  END IF;

  IF v_campaign_count <> v_bundle.expected_campaign_count
    OR v_child_index_count <> v_bundle.expected_campaign_count
    OR v_min_child_index <> 0
    OR v_max_child_index <> v_bundle.expected_campaign_count - 1
    OR v_invalid_campaign_count <> 0
    OR v_registered_count <> v_bundle.expected_campaign_count
    OR v_distinct_group_count <> 1
    OR v_invalid_source_count <> 0
  THEN
    RAISE EXCEPTION 'campaign_creation_bundle_registration_invalid';
  END IF;

  -- This update is not externally visible until every snapshot succeeds. It
  -- is intentionally first so the router can distinguish this transaction's
  -- final baseline from ordinary ingest against a staged child.
  UPDATE public.auto_campaign_creation_bundles AS bundle
  SET data_group_id = v_group.id,
      baseline_revision = v_group.revision,
      ready_campaign_count = bundle.expected_campaign_count,
      status = 'ready',
      error = NULL,
      updated_at = now()
  WHERE bundle.id = p_bundle_id
  RETURNING bundle.* INTO v_bundle;

  UPDATE public.auto_campaign_data_group_sources AS source
  SET baseline_revision = v_group.revision,
      status = 'baselining',
      started_at = NULL,
      stopped_at = NULL,
      stop_reason = NULL,
      last_ingest_at = NULL,
      updated_at = now()
  WHERE source.bundle_id = p_bundle_id;

  SELECT count(*)::integer
  INTO v_active_membership_count
  FROM public.auto_account_contact_group_members AS member
  WHERE member.group_id = v_group.id
    AND member.is_delete = false;

  FOR v_bundle_source IN
    SELECT source.id, source.campaign_id
    FROM public.auto_campaign_data_group_sources AS source
    WHERE source.bundle_id = p_bundle_id
    ORDER BY source.campaign_id, source.id
  LOOP
    v_snapshot := public.aka_agent_internal_route_group_snapshot(
      v_bundle_source.id, v_batch.id, v_group.revision
    );

    IF COALESCE((v_snapshot ->> 'inserted_input_count')::integer, 0)
         + COALESCE((v_snapshot ->> 'already_seen_input_count')::integer, 0)
         + COALESCE((v_snapshot ->> 'incompatible_count')::integer, 0)
         + COALESCE((v_snapshot ->> 'conflict_count')::integer, 0)
       <> v_active_membership_count
    THEN
      RAISE EXCEPTION 'campaign_creation_bundle_baseline_incomplete';
    END IF;

    UPDATE public.auto_campaigns AS campaign
    SET note = CASE
          WHEN COALESCE((v_snapshot ->> 'inserted_input_count')::integer, 0)
             + COALESCE((v_snapshot ->> 'already_seen_input_count')::integer, 0) = 0
            THEN 'Chờ data phù hợp'
          WHEN campaign.note IN ('Chờ data phù hợp', 'Chờ data mới') THEN NULL
          ELSE campaign.note
        END,
        updated_at = now()
    WHERE campaign.id = v_bundle_source.campaign_id;
  END LOOP;

  UPDATE public.auto_campaign_data_group_sources AS source
  SET status = 'active',
      baseline_revision = v_group.revision,
      started_at = COALESCE(source.started_at, now()),
      stopped_at = NULL,
      stop_reason = NULL,
      last_ingest_at = now(),
      updated_at = now()
  WHERE source.bundle_id = p_bundle_id;

  UPDATE public.auto_campaigns AS campaign
  SET provisioning_state = 'ready',
      updated_at = now()
  WHERE campaign.creation_bundle_id = p_bundle_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false;

  SELECT source.*
  INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = v_campaign.id;

  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
  WHERE id = v_batch.id;

  RETURN to_jsonb(v_source);
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_reactivate_campaign_data_group_source(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_request_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_hash text;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_data_group_source_request';
  END IF;

  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = p_campaign_id AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_data_group_source_not_found'; END IF;
  SELECT * INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = v_source.group_id AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group' AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  -- Reactivation routes the existing group snapshot after locking campaign and
  -- source rows. Join the common campaign/input barrier before either of those
  -- row locks so the nested legacy router can re-enter it without inversion.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account ON account.id = campaign.account_id
  WHERE campaign.id = p_campaign_id AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
  FOR UPDATE OF campaign, account;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false)
    OR v_campaign.data_group_id IS DISTINCT FROM v_source.group_id
    OR v_campaign.data_target_source_mode <> 'data_group'
    OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now()) THEN
    RAISE EXCEPTION 'data_group_campaign_terminal';
  END IF;
  -- Re-lock in the shared group -> campaign -> source order used by bind and
  -- intake, then verify the optimistic source read did not change underneath.
  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = v_source.id
    AND source.campaign_id = p_campaign_id
    AND source.group_id = v_group.id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'campaign_data_group_source_changed'; END IF;
  IF v_source.status <> 'stopped' THEN RETURN to_jsonb(v_source); END IF;

  v_hash := md5(jsonb_build_object(
    'operation', 'reactivate_source', 'campaignId', p_campaign_id,
    'groupId', v_source.group_id
  )::text);
  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, request_hash, status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'reactivate_source', v_source.group_id, v_hash,
    'processing', p_staff_id, p_organization_id
  ) ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;
  IF NOT FOUND THEN
    SELECT * INTO v_batch FROM public.auto_data_ingest_batches
    WHERE staff_id = p_staff_id AND organization_id = p_organization_id
      AND request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'reactivate_source' OR v_batch.request_hash <> v_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  UPDATE public.auto_campaign_data_group_sources
  SET status = 'baselining', stopped_at = NULL, stop_reason = NULL, updated_at = now()
  WHERE id = v_source.id RETURNING * INTO v_source;
  PERFORM public.aka_agent_internal_route_group_snapshot(
    v_source.id, v_batch.id, v_group.revision
  );
  UPDATE public.auto_campaign_data_group_sources
  SET status = 'active', baseline_revision = v_group.revision,
      started_at = COALESCE(started_at, now()), last_ingest_at = now(), updated_at = now()
  WHERE id = v_source.id RETURNING * INTO v_source;
  UPDATE public.auto_campaigns
  SET status = CASE WHEN status = 'hoàn thành' THEN 'chờ xử lý' ELSE status END,
      completed_at = CASE WHEN status = 'hoàn thành' THEN NULL ELSE completed_at END,
      note = CASE WHEN status = 'hoàn thành' THEN 'Chờ data mới' ELSE note END,
      updated_at = now()
  WHERE id = v_campaign.id;
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = to_jsonb(v_source), updated_at = now()
  WHERE id = v_batch.id;
  RETURN to_jsonb(v_source);
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_snapshot_data_group_to_direct_campaign(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_campaign_id bigint, p_group_id bigint, p_campaign_schedule timestamp with time zone, p_campaign_status text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_action_id text;
  v_completed_result jsonb;
  v_previous_target text := current_setting(
    'aka_agent.zalo_runtime_target', true
  );
  v_runtime_target text := 'desktop';
  v_result jsonb;
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  -- Preserve the pre-v206 retry contract: a committed request returns its
  -- immutable result even if the group/account subtype changed afterward.
  -- No campaign/input mutation occurs on this branch.
  SELECT batch.result
  INTO v_completed_result
  FROM public.auto_data_ingest_batches AS batch
  WHERE batch.staff_id = p_staff_id
    AND batch.organization_id = p_organization_id
    AND batch.request_id = btrim(COALESCE(p_request_id, ''))
    AND batch.operation = 'snapshot_campaign'
    AND batch.group_id = p_group_id
    AND batch.result IS NOT NULL;

  IF v_completed_result IS NULL THEN
    SELECT campaign.action_id
    INTO v_action_id
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_account_contact_groups AS contact_group
      ON contact_group.id = p_group_id
     AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
     AND contact_group.organization_id = p_organization_id
     AND contact_group.purpose = 'data_group'
     AND contact_group.is_delete = false
    WHERE campaign.id = p_campaign_id
      AND campaign.staff_id = p_staff_id
      AND campaign.organization_id = p_organization_id
      AND COALESCE(campaign.is_delete, false) = false;

    IF v_action_id IS NOT NULL
      AND NOT public.aka_agent_data_group_type_compatible(
        p_group_id, v_action_id
      )
    THEN
      RAISE EXCEPTION 'data_group_campaign_semantic_type_incompatible';
    END IF;
  END IF;

  -- The desktop app is a tenant control surface for both runtime owners. Route
  -- this DB-only provisioning mutation by the persisted account subtype, then
  -- let the core repeat the proof under its campaign/account locks.
  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_runtime_target
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = campaign.staff_id
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false
    AND (account.organization_id IS NULL
      OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false;

  v_runtime_target := COALESCE(v_runtime_target, 'desktop');
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', v_runtime_target, true
  );
  BEGIN
    v_result := public.aka_agent_snapshot_data_group_to_direct_campaign_v205_internal(
      p_staff_id,
      p_organization_id,
      p_request_id,
      p_campaign_id,
      p_group_id,
      p_campaign_schedule,
      p_campaign_status,
      p_auth_username,
      p_auth_password
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
    );
    RAISE;
  END;
  PERFORM set_config(
    'aka_agent.zalo_runtime_target', COALESCE(v_previous_target, ''), true
  );
  RETURN v_result;
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_snapshot_data_group_to_direct_campaign_v205_internal(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_campaign_id bigint, p_group_id bigint, p_campaign_schedule timestamp with time zone, p_campaign_status text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_member public.auto_account_contact_group_members%ROWTYPE;
  v_contact public.auto_account_contacts%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_action text;
  v_platform text;
  v_contact_type text;
  v_name text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_input_uid text;
  v_input_phone text;
  v_input_email text;
  v_target_value text;
  v_identity_value text;
  v_uid_identity text;
  v_url_identity text;
  v_allow_alias_resolution boolean;
  v_target_kind text;
  v_scope text;
  v_candidate_key text;
  v_canonical_key text;
  v_aliases text[];
  v_mapped_keys text[];
  v_payload jsonb;
  v_input_id bigint;
  v_inserted_row boolean;
  v_info1 text;
  v_info2 text;
  v_info3 text;
  v_info4 text;
  v_info5 text;
  v_phone_carrier text;
  v_request_hash text;
  v_result jsonb;
  v_active integer := 0;
  v_inserted integer := 0;
  v_existing integer := 0;
  v_incompatible integer := 0;
  v_conflict integer := 0;
  v_account_runtime_target text;
  v_runtime_target text := lower(btrim(COALESCE(
    NULLIF(current_setting('aka_agent.zalo_runtime_target', true), ''),
    'desktop'
  )));
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_group_id IS NULL OR p_group_id <= 0
    OR p_campaign_schedule IS NULL
    OR p_campaign_status IS NULL
    OR p_campaign_status NOT IN ('chờ xử lý', 'tạm dừng')
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_direct_campaign_group_snapshot';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'snapshot_campaign',
    'campaignId', p_campaign_id,
    'groupId', p_group_id,
    'campaignSchedule', to_char(
      p_campaign_schedule AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US'
    ),
    'campaignStatus', p_campaign_status
  )::text);

  -- Return a committed response before consulting mutable campaign/group state.
  -- This makes response-loss retries stable even if the group changes later.
  SELECT batch.*
  INTO v_batch
  FROM public.auto_data_ingest_batches AS batch
  WHERE batch.staff_id = p_staff_id
    AND batch.organization_id = p_organization_id
    AND batch.request_id = btrim(p_request_id)
  FOR UPDATE;
  IF FOUND THEN
    IF v_batch.operation <> 'snapshot_campaign'
      OR v_batch.group_id IS DISTINCT FROM p_group_id
      OR v_batch.request_hash <> v_request_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  -- Match the shared Data Group lock hierarchy (group -> campaign) used by
  -- ingest/bind/delete; do not invert those locks during live intake.
  SELECT contact_group.*
  INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  -- Keep the shared Data Group hierarchy: batch -> group -> barrier ->
  -- campaign -> account/input. Bind/reactivate/router paths take the same
  -- group-before-barrier order.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.*
  INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false) THEN
    RAISE EXCEPTION 'campaign_not_found';
  END IF;
  IF v_campaign.data_target_source_mode IS DISTINCT FROM 'direct'
    OR v_campaign.provisioning_state IS DISTINCT FROM 'ready'
    OR v_campaign.status = 'đang chạy'
    OR EXISTS (
      SELECT 1
      FROM public.auto_campaign_data_group_sources AS source
      WHERE source.campaign_id = v_campaign.id
    )
  THEN
    RAISE EXCEPTION 'campaign_not_direct_snapshot_eligible';
  END IF;
  IF v_campaign.action_id NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    RAISE EXCEPTION 'data_group_campaign_action_incompatible';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_campaign_actions AS action
    WHERE action.id = v_campaign.action_id
      AND action.is_active = true
      AND COALESCE(action.is_delete, false) = false
  ) THEN
    RAISE EXCEPTION 'campaign_action_inactive';
  END IF;
  -- Campaign is already locked above. Lock account second so campaign claims
  -- and subtype conversion cannot race this runtime ownership decision.
  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_account_runtime_target
  FROM public.auto_accounts AS account
  WHERE account.id = v_campaign.account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
  FOR SHARE OF account;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign_account_not_found';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server')
    OR v_runtime_target IS DISTINCT FROM v_account_runtime_target
  THEN
    RAISE EXCEPTION 'direct_campaign_runtime_not_owner';
  END IF;

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, kind, source_name, request_hash,
    status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'snapshot_campaign', v_group.id, 'manual',
    'Snapshot Nhóm data: ' || v_group.name, v_request_hash,
    'processing', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT batch.*
    INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'snapshot_campaign'
      OR v_batch.group_id IS DISTINCT FROM v_group.id
      OR v_batch.request_hash <> v_request_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  v_action := btrim(COALESCE(v_campaign.action_id, ''));

  FOR v_member IN
    SELECT member.*
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id
      AND member.is_delete = false
    ORDER BY member.id
  LOOP
    v_active := v_active + 1;
    v_input_uid := NULL;
    v_input_phone := NULL;
    v_input_email := NULL;
    v_target_value := NULL;
    v_identity_value := NULL;
    v_uid_identity := NULL;
    v_url_identity := NULL;
    v_target_kind := NULL;
    v_scope := NULL;
    v_candidate_key := NULL;
    v_canonical_key := NULL;
    v_aliases := '{}'::text[];
    v_mapped_keys := '{}'::text[];
    v_allow_alias_resolution := false;
    v_input_id := NULL;
    v_inserted_row := false;

    IF NOT (
      -- v228: valid-phone routes ignore all source semantic and contact
      -- metadata constraints; UID-only add-member still uses the old guard.
      v_action IN ('zalo_message_phone', 'zalo_add_group_member')
      AND public.aka_agent_data_group_membership_has_valid_phone(
        v_member.id, v_group.id
      )
    ) AND NOT public.aka_agent_data_group_membership_semantic_compatible(
      v_member.id, v_action, v_group.id
    ) THEN
      v_incompatible := v_incompatible + 1;
      CONTINUE;
    END IF;

    SELECT contact.*
    INTO v_contact
    FROM public.auto_account_contacts AS contact
    WHERE contact.id = v_member.contact_id
      AND contact.staff_id = v_group.staff_id
      AND contact.organization_id = p_organization_id
      AND COALESCE(contact.is_delete, false) = false;
    IF NOT FOUND THEN
      v_incompatible := v_incompatible + 1;
      CONTINUE;
    END IF;

    v_platform := lower(btrim(COALESCE(v_contact.flatform_type, '')));
    v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
    v_name := NULLIF(btrim(COALESCE(v_contact.name, '')), '');
    v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
    v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
    v_phone := public.aka_agent_internal_normalize_phone(COALESCE(
      NULLIF(v_contact.phone, ''),
      NULLIF(v_contact.extra_data ->> 'phone', ''),
      CASE WHEN v_contact_type = 'phone' THEN v_contact.uid ELSE NULL END,
      ''
    ));
    v_phone := NULLIF(v_phone, '');
    v_email := NULLIF(lower(btrim(COALESCE(
      NULLIF(v_contact.email, ''),
      NULLIF(v_contact.extra_data ->> 'email', ''),
      CASE WHEN v_contact_type = 'email' THEN v_contact.uid ELSE NULL END,
      ''
    ))), '');
    IF v_email IS NOT NULL AND (
      v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
      OR length(v_email) > 254
    ) THEN
      v_email := NULL;
    END IF;
    v_info1 := NULLIF(v_contact.extra_data ->> 'info1', '');
    v_info2 := NULLIF(v_contact.extra_data ->> 'info2', '');
    v_info3 := NULLIF(v_contact.extra_data ->> 'info3', '');
    v_info4 := NULLIF(v_contact.extra_data ->> 'info4', '');
    v_info5 := NULLIF(v_contact.extra_data ->> 'info5', '');
    v_phone_carrier := COALESCE(
      NULLIF(v_contact.extra_data ->> 'phoneCarrier', ''),
      NULLIF(v_contact.extra_data ->> 'phone_carrier', '')
    );

    IF v_action IN ('facebook_group_post', 'facebook_join_group', 'facebook_find_data_group') THEN
      -- v227: snapshot Facebook routes use semantic type plus UID/URL only.
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'facebook_group'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action = 'facebook_message_uid' THEN
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'facebook_person'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action = 'facebook_find_data_search' THEN
      v_target_value := v_uid;
      v_target_kind := 'facebook_search'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action IN ('facebook_comment_seeding', 'facebook_comment_seeding_post') THEN
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := CASE WHEN v_action = 'facebook_comment_seeding_post'
        THEN 'facebook_post' ELSE 'facebook_comment_target' END;
      v_scope := 'portable'; v_input_uid := v_target_value;
    ELSIF v_action = 'zalo_message_phone' THEN
      IF v_phone IS NULL THEN v_incompatible := v_incompatible + 1; CONTINUE; END IF;
      v_target_value := v_phone; v_target_kind := 'phone'; v_scope := 'portable';
      v_input_phone := v_phone;
    ELSIF v_action = 'zalo_join_group_link' THEN
      IF v_platform <> 'zalo' OR v_contact_type <> 'group' THEN
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'zalo_group_link'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action = 'email_send' THEN
      IF v_email IS NULL THEN v_incompatible := v_incompatible + 1; CONTINUE; END IF;
      v_target_value := v_email; v_target_kind := 'email'; v_scope := 'portable';
      v_input_email := v_email;
    ELSIF v_action IN ('facebook_message_friend', 'facebook_group_invite') THEN
      -- v226: Facebook UID/URL targets do not inherit source-account or
      -- is_friend restrictions from scan metadata.
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'facebook_person';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_target_value;
    ELSIF v_action = 'facebook_page_post' THEN
      -- v226: Page ID/URL validity is sufficient for a Facebook target.
      v_target_value := COALESCE(v_uid, v_url);
      v_target_kind := 'facebook_page';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_target_value;
    ELSIF v_action IN (
      'zalo_message_friend', 'zalo_message_group_member',
      'zalo_message_remarketing_customer'
    ) THEN
      IF v_platform <> 'zalo' OR v_contact_type <> 'person'
        OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id
        OR (v_action = 'zalo_message_friend' AND v_contact.is_friend IS DISTINCT FROM true)
      THEN
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
      v_target_value := v_uid; v_target_kind := 'zalo_person';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_uid;
    ELSIF v_action = 'zalo_message_group' THEN
      IF v_platform <> 'zalo' OR v_contact_type <> 'group'
        OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id
        OR v_contact.is_joined IS DISTINCT FROM true
      THEN
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
      v_target_value := v_uid; v_target_kind := 'zalo_group';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_uid;
    ELSIF v_action = 'zalo_add_group_member' THEN
      IF v_phone IS NOT NULL THEN
        v_target_value := v_phone; v_target_kind := 'phone'; v_scope := 'portable';
        v_input_phone := v_phone; v_input_uid := '';
      ELSIF v_platform = 'zalo' AND v_contact_type = 'person'
        AND v_uid IS NOT NULL
        AND v_contact.account_id IS NOT DISTINCT FROM v_campaign.account_id
      THEN
        v_target_value := v_uid; v_target_kind := 'zalo_person';
        v_scope := 'bound:' || v_campaign.account_id::text;
        v_input_uid := v_uid;
      ELSE
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
    ELSE
      v_incompatible := v_incompatible + 1; CONTINUE;
    END IF;

    IF NULLIF(v_target_value, '') IS NULL THEN
      v_incompatible := v_incompatible + 1; CONTINUE;
    END IF;

    IF v_target_kind LIKE 'facebook_%' THEN
      v_uid_identity := CASE WHEN v_uid IS NULL THEN NULL
        ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_uid), '') END;
      v_url_identity := CASE WHEN v_url IS NULL THEN NULL
        ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_url), '') END;
      v_identity_value := COALESCE(
        v_uid_identity,
        v_url_identity,
        NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_target_value), '')
      );
      v_allow_alias_resolution := true;
    ELSIF v_target_kind = 'email' THEN
      v_identity_value := lower(v_target_value);
    ELSE
      v_identity_value := v_target_value;
    END IF;
    IF NULLIF(v_identity_value, '') IS NULL THEN
      v_incompatible := v_incompatible + 1; CONTINUE;
    END IF;

    v_candidate_key := v_scope || ':' || v_target_kind || ':' || v_identity_value;
    v_aliases := array_append(v_aliases, v_candidate_key);
    IF v_target_kind LIKE 'facebook_%' AND v_uid_identity IS NOT NULL THEN
      v_aliases := array_append(
        v_aliases, v_scope || ':' || v_target_kind || ':' || v_uid_identity
      );
    END IF;
    IF v_target_kind LIKE 'facebook_%' AND v_url_identity IS NOT NULL THEN
      v_aliases := array_append(
        v_aliases, v_scope || ':' || v_target_kind || ':' || v_url_identity
      );
    END IF;

    SELECT COALESCE(array_agg(DISTINCT alias.canonical_target_key), '{}'::text[])
    INTO v_mapped_keys
    FROM public.auto_campaign_input_target_aliases AS alias
    WHERE alias.campaign_id = v_campaign.id
      AND alias.alias_key = ANY(v_aliases);

    IF cardinality(v_mapped_keys) > 1
      OR (
        cardinality(v_mapped_keys) = 1
        AND NOT v_allow_alias_resolution
        AND v_mapped_keys[1] IS DISTINCT FROM v_candidate_key
      )
    THEN
      UPDATE public.auto_campaign_input_target_aliases AS alias
      SET conflict_count = alias.conflict_count + 1,
          last_conflict_at = now(),
          last_conflict_payload = jsonb_build_object(
            'membershipId', v_member.id,
            'candidateCanonicalKey', v_candidate_key,
            'mappedCanonicalKeys', to_jsonb(v_mapped_keys),
            'aliases', to_jsonb(v_aliases),
            'snapshotBatchId', v_batch.id
          ),
          updated_at = now()
      WHERE alias.campaign_id = v_campaign.id
        AND alias.alias_key = ANY(v_aliases);
      v_conflict := v_conflict + 1;
      CONTINUE;
    END IF;

    v_canonical_key := CASE
      WHEN v_allow_alias_resolution AND cardinality(v_mapped_keys) = 1
        THEN v_mapped_keys[1]
      ELSE v_candidate_key
    END;
    v_payload := jsonb_strip_nulls(jsonb_build_object(
      'name', COALESCE(v_name, v_target_value),
      'phone', v_input_phone,
      'phone_carrier', v_phone_carrier,
      'uid', v_input_uid,
      'email', v_input_email,
      'info1', v_info1,
      'info2', v_info2,
      'info3', v_info3,
      'info4', v_info4,
      'info5', v_info5,
      'contact_id', v_contact.id,
      'membership_id', v_member.id,
      'source_account_id', v_contact.account_id,
      'contact_type', v_contact.contact_type,
      'flatform_type', v_contact.flatform_type,
      'canonical_target_key', v_canonical_key,
      'snapshot_group_id', v_group.id,
      'snapshot_group_revision', v_group.revision
    ));

    -- Reuse order for one-time snapshots:
    --   1. the active canonical row;
    --   2. an active row already mapped by one of this target's aliases;
    --   3. the oldest active legacy row whose action target normalizes equally;
    --   4. a newly inserted canonical row.
    -- Legacy rows remain canonical_target_key=NULL.  Aliases and immutable
    -- origin provenance below make every later snapshot resolve to that row.
    SELECT input_data.id
    INTO v_input_id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = v_campaign.id
      AND input_data.canonical_target_key = v_canonical_key
      AND COALESCE(input_data.is_delete, false) = false
    ORDER BY input_data.id
    LIMIT 1
    FOR UPDATE;

    IF v_input_id IS NULL THEN
      SELECT input_data.id
      INTO v_input_id
      FROM public.auto_campaign_input_target_aliases AS alias
      JOIN public.auto_campaign_input_data AS input_data
        ON input_data.id = alias.input_data_id
       AND input_data.campaign_id = v_campaign.id
       AND COALESCE(input_data.is_delete, false) = false
       AND (
         input_data.canonical_target_key IS NULL
         OR input_data.canonical_target_key = v_canonical_key
       )
      WHERE alias.campaign_id = v_campaign.id
        AND alias.canonical_target_key = v_canonical_key
        AND alias.alias_key = ANY(v_aliases)
      ORDER BY input_data.id
      LIMIT 1
      FOR UPDATE OF input_data;
    END IF;

    IF v_input_id IS NULL THEN
      SELECT input_data.id
      INTO v_input_id
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.campaign_id = v_campaign.id
        AND input_data.canonical_target_key IS NULL
        AND COALESCE(input_data.is_delete, false) = false
        AND CASE
          WHEN v_target_kind = 'phone' THEN
            public.aka_agent_internal_normalize_phone(
              COALESCE(input_data.phone, '')
            ) = v_identity_value
          WHEN v_target_kind = 'email' THEN
            lower(btrim(COALESCE(input_data.email, ''))) = v_identity_value
          WHEN v_target_kind LIKE 'facebook_%' THEN
            (
              v_scope || ':' || v_target_kind || ':' ||
              public.aka_agent_internal_normalize_facebook_identity(
                COALESCE(input_data.uid, '')
              )
            ) = ANY(v_aliases)
          ELSE
            btrim(COALESCE(input_data.uid, '')) = v_identity_value
        END
      ORDER BY input_data.id
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_input_id IS NULL THEN
      INSERT INTO public.auto_campaign_input_data (
        campaign_id, input_id, name, phone, phone_carrier, uid, email,
        info1, info2, info3, info4, info5, status, schedule, is_delete,
        canonical_target_key, created_at
      ) VALUES (
        v_campaign.id, NULL, COALESCE(v_name, v_target_value),
        v_input_phone, v_phone_carrier, v_input_uid, v_input_email,
        v_info1, v_info2, v_info3, v_info4, v_info5,
        'chờ xử lý', p_campaign_schedule, false,
        v_canonical_key, now()
      )
      ON CONFLICT (campaign_id, canonical_target_key)
        WHERE canonical_target_key IS NOT NULL AND COALESCE(is_delete, false) = false
      DO NOTHING
      RETURNING id INTO v_input_id;

      IF v_input_id IS NULL THEN
        SELECT input_data.id
        INTO v_input_id
        FROM public.auto_campaign_input_data AS input_data
        WHERE input_data.campaign_id = v_campaign.id
          AND input_data.canonical_target_key = v_canonical_key
          AND COALESCE(input_data.is_delete, false) = false
        FOR UPDATE;
      ELSE
        v_inserted_row := true;
      END IF;
    END IF;

    INSERT INTO public.auto_campaign_input_target_aliases (
      campaign_id, alias_key, canonical_target_key, input_data_id
    )
    SELECT v_campaign.id, candidate.alias_key, v_canonical_key, v_input_id
    FROM (SELECT DISTINCT unnest(v_aliases) AS alias_key) AS candidate
    ON CONFLICT (campaign_id, alias_key) DO UPDATE
    SET input_data_id = EXCLUDED.input_data_id,
        updated_at = now()
    WHERE auto_campaign_input_target_aliases.canonical_target_key
      = EXCLUDED.canonical_target_key;

    INSERT INTO public.auto_campaign_input_origins (
      input_data_id, source_id, group_id, membership_id, batch_id,
      origin_kind, group_revision, canonical_target_key, payload_snapshot
    ) VALUES (
      v_input_id, NULL, v_group.id, v_member.id, v_batch.id,
      'group', v_group.revision, v_canonical_key, v_payload
    ) ON CONFLICT DO NOTHING;

    IF v_inserted_row THEN
      v_inserted := v_inserted + 1;
    ELSE
      v_existing := v_existing + 1;
    END IF;
  END LOOP;

  IF v_inserted > 0 THEN
    UPDATE public.auto_campaigns AS campaign
    SET schedule = p_campaign_schedule,
        original_schedule = p_campaign_schedule,
        status = p_campaign_status,
        note = CASE
          WHEN campaign.note IN ('Chờ data phù hợp', 'Chờ data mới') THEN NULL
          ELSE campaign.note
        END,
        updated_at = now()
    WHERE campaign.id = v_campaign.id;
  END IF;

  v_result := jsonb_build_object(
    'request_id', btrim(p_request_id),
    'campaign_id', v_campaign.id,
    'group_id', v_group.id,
    'group_revision', v_group.revision,
    'active_membership_count', v_active,
    'inserted_count', v_inserted,
    'already_seen_count', v_existing,
    'incompatible_count', v_incompatible,
    'conflict_count', v_conflict
  );

  UPDATE public.auto_data_ingest_batches AS batch
  SET status = 'completed', result = v_result, updated_at = now()
  WHERE batch.id = v_batch.id;

  RETURN v_result;
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_preflight_campaign_data_group_change(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_group_id bigint)
 RETURNS TABLE(allowed boolean, reason text, canonical_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_runtime_target text := CASE
    WHEN NULLIF(btrim(COALESCE(
      current_setting('aka_agent.zalo_runtime_target', true), ''
    )), '') = 'desktop' THEN 'desktop'
    ELSE 'server'
  END;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  canonical_count := 0;

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false) THEN
    allowed := false;
    reason := 'data_group_campaign_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  -- Ownership precedes every early-return branch, including `unchanged`, so a
  -- service caller cannot reuse a source after its Zalo account becomes local.
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_accounts AS account
    WHERE account.id = v_campaign.account_id
      AND account.staff_id = p_staff_id
      AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
      AND COALESCE(account.is_delete, false) = false
      AND (
        COALESCE(account.flatform_type, '') <> 'zalo'
        OR (
          account.organization_id = p_organization_id
          AND (
            (
              v_runtime_target = 'desktop'
              AND COALESCE(account.is_zalo_server, false) = false
            )
            OR (
              v_runtime_target = 'server'
              AND COALESCE(account.is_zalo_show_web, false) = false
              AND COALESCE(account.is_zalo_server, false) = true
              AND COALESCE(account.is_active, true) = true
            )
          )
        )
      )
  ) THEN
    allowed := false;
    reason := 'data_group_campaign_account_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT count(*)::bigint INTO canonical_count
  FROM public.auto_campaign_input_data AS input_row
  WHERE input_row.campaign_id = v_campaign.id
    AND input_row.canonical_target_key IS NOT NULL
    AND COALESCE(input_row.is_delete, false) = false;

  IF p_group_id IS NULL OR p_group_id <= 0 OR NOT EXISTS (
    SELECT 1
    FROM public.auto_account_contact_groups AS contact_group
    WHERE contact_group.id = p_group_id
      AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
      AND contact_group.organization_id = p_organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false
  ) THEN
    allowed := false;
    reason := 'data_group_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_campaign.data_target_source_mode = 'data_group'
    AND v_campaign.data_group_id IS NOT DISTINCT FROM p_group_id
  THEN
    allowed := true;
    reason := 'unchanged';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_campaign.status IN ('đang chạy', 'hoàn thành')
    OR (v_campaign.schedule_end_date IS NOT NULL
      AND v_campaign.schedule_end_date <= now())
  THEN
    allowed := false;
    reason := 'data_group_campaign_not_bindable';
    RETURN NEXT;
    RETURN;
  END IF;
  IF v_campaign.action_id NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    allowed := false;
    reason := 'data_group_campaign_action_incompatible';
    RETURN NEXT;
    RETURN;
  END IF;
  IF canonical_count > 0 THEN
    allowed := false;
    reason := 'campaign_data_group_source_immutable_after_intake';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT source.* INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = v_campaign.id
    AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id;
  IF FOUND AND v_source.bundle_id IS NOT NULL THEN
    allowed := false;
    reason := 'campaign_data_group_source_immutable';
    RETURN NEXT;
    RETURN;
  END IF;

  allowed := true;
  reason := 'allowed';
  RETURN NEXT;
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_preview_data_group_campaign_targets(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_action_id text, p_account_ids bigint[])
 RETURNS TABLE(account_id bigint, active_membership_count bigint, compatible_membership_count bigint, valid_target_count bigint, incompatible_membership_count bigint, duplicate_target_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_action text := btrim(COALESCE(p_action_id, ''));
  v_requested_account_count integer;
  v_valid_account_count integer;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF p_group_id IS NULL OR p_group_id <= 0
    OR p_account_ids IS NULL
    OR cardinality(p_account_ids) NOT BETWEEN 1 AND 100
    OR EXISTS (
      SELECT 1 FROM unnest(p_account_ids) AS requested(id)
      WHERE requested.id IS NULL OR requested.id <= 0
    )
  THEN
    RAISE EXCEPTION 'invalid_data_group_campaign_preview';
  END IF;
  IF v_action NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    RAISE EXCEPTION 'data_group_campaign_action_incompatible';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_account_contact_groups AS contact_group
    WHERE contact_group.id = p_group_id
      AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
      AND contact_group.organization_id = p_organization_id
      AND contact_group.purpose = 'data_group'
      AND contact_group.is_delete = false
  ) THEN
    RAISE EXCEPTION 'data_group_not_found';
  END IF;
  IF NOT public.aka_agent_data_group_type_compatible(p_group_id, v_action) THEN
    RAISE EXCEPTION 'data_group_campaign_semantic_type_incompatible';
  END IF;

  SELECT count(DISTINCT requested.id)::integer
  INTO v_requested_account_count
  FROM unnest(p_account_ids) AS requested(id);

  SELECT count(DISTINCT account.id)::integer
  INTO v_valid_account_count
  FROM unnest(p_account_ids) AS requested(id)
  JOIN public.auto_accounts AS account
    ON account.id = requested.id
  WHERE account.staff_id = p_staff_id
    AND (
      account.organization_id IS NULL
      OR account.organization_id = p_organization_id
    )
    AND COALESCE(account.is_delete, false) = false;
  IF v_valid_account_count IS DISTINCT FROM v_requested_account_count THEN
    RAISE EXCEPTION 'data_group_campaign_account_not_found';
  END IF;

  RETURN QUERY
  WITH requested_accounts AS (
    SELECT DISTINCT requested.id AS account_id
    FROM unnest(p_account_ids) AS requested(id)
  ), active_members AS (
    SELECT member.id AS membership_id
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = p_group_id
      AND member.is_delete = false
  ), routed AS (
    SELECT
      requested.account_id,
      member.membership_id,
      public.aka_agent_internal_preview_data_group_target_key(
        p_staff_id,
        p_organization_id,
        p_group_id,
        member.membership_id,
        v_action,
        requested.account_id
      ) AS target_key
    FROM requested_accounts AS requested
    LEFT JOIN active_members AS member ON true
  ), counts AS (
    SELECT
      routed.account_id,
      count(routed.membership_id)::bigint AS active_count,
      count(routed.membership_id) FILTER (
        WHERE routed.target_key IS NOT NULL
      )::bigint AS compatible_count,
      count(DISTINCT routed.target_key)::bigint AS target_count
    FROM routed
    GROUP BY routed.account_id
  )
  SELECT
    counts.account_id,
    counts.active_count,
    counts.compatible_count,
    counts.target_count,
    counts.active_count - counts.compatible_count,
    counts.compatible_count - counts.target_count
  FROM counts
  ORDER BY counts.account_id;
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_internal_preview_data_group_target_key(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_membership_id bigint, p_action_id text, p_account_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_contact public.auto_account_contacts%ROWTYPE;
  v_action text := btrim(COALESCE(p_action_id, ''));
  v_platform text;
  v_contact_type text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_target_value text;
  v_identity_value text;
  v_target_kind text;
  v_scope text;
BEGIN
  IF NOT (
    -- v228: preview applies the same valid-phone-only route as materialization.
    v_action IN ('zalo_message_phone', 'zalo_add_group_member')
    AND public.aka_agent_data_group_membership_has_valid_phone(
      p_membership_id, p_group_id
    )
  ) AND NOT public.aka_agent_data_group_membership_semantic_compatible(
    p_membership_id, v_action, p_group_id
  ) THEN
    RETURN NULL;
  END IF;

  SELECT contact.*
  INTO v_contact
  FROM public.auto_account_contact_group_members AS member
  JOIN public.auto_account_contacts AS contact
    ON contact.id = member.contact_id
  WHERE member.id = p_membership_id
    AND member.group_id = p_group_id
    AND member.is_delete = false
    AND private.shared_data_member_owner(p_group_id,contact.staff_id,p_staff_id,p_organization_id)
    AND contact.organization_id = p_organization_id
    AND COALESCE(contact.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_platform := lower(btrim(COALESCE(v_contact.flatform_type, '')));
  v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
  v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
  v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
  v_phone := NULLIF(public.aka_agent_internal_normalize_phone(COALESCE(
    NULLIF(v_contact.phone, ''),
    NULLIF(v_contact.extra_data ->> 'phone', ''),
    CASE WHEN v_contact_type = 'phone' THEN v_contact.uid ELSE NULL END,
    ''
  )), '');
  v_email := NULLIF(lower(btrim(COALESCE(
    NULLIF(v_contact.email, ''),
    NULLIF(v_contact.extra_data ->> 'email', ''),
    CASE WHEN v_contact_type = 'email' THEN v_contact.uid ELSE NULL END,
    ''
  ))), '');
  IF v_email IS NOT NULL AND (
    v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    OR length(v_email) > 254
  ) THEN
    v_email := NULL;
  END IF;

  IF v_action IN (
    'facebook_group_post', 'facebook_join_group',
    'facebook_find_data_group'
  ) THEN
    -- v227: preview Facebook routes use semantic type plus UID/URL only.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_group';
    v_scope := 'portable';
  ELSIF v_action = 'facebook_message_uid' THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    v_scope := 'portable';
  ELSIF v_action = 'facebook_find_data_search' THEN
    v_target_value := v_uid;
    v_target_kind := 'facebook_search';
    v_scope := 'portable';
  ELSIF v_action IN (
    'facebook_comment_seeding', 'facebook_comment_seeding_post'
  ) THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := CASE
      WHEN v_action = 'facebook_comment_seeding_post' THEN 'facebook_post'
      ELSE 'facebook_comment_target'
    END;
    v_scope := 'portable';
  ELSIF v_action = 'zalo_message_phone' THEN
    IF v_phone IS NULL THEN
      RETURN NULL;
    END IF;
    v_target_value := v_phone;
    v_target_kind := 'phone';
    v_scope := 'portable';
  ELSIF v_action = 'zalo_join_group_link' THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'group' THEN
      RETURN NULL;
    END IF;
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'zalo_group_link';
    v_scope := 'portable';
  ELSIF v_action = 'email_send' THEN
    IF v_email IS NULL THEN
      RETURN NULL;
    END IF;
    v_target_value := v_email;
    v_target_kind := 'email';
    v_scope := 'portable';
  ELSIF v_action IN ('facebook_message_friend', 'facebook_group_invite') THEN
    -- v226: preview follows the portable Facebook UID/URL route.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action = 'facebook_page_post' THEN
    v_target_value := COALESCE(v_uid, v_url);
    v_target_kind := 'facebook_page';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action IN (
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer'
  ) THEN
    IF v_platform <> 'zalo'
      OR v_contact_type <> 'person'
      OR v_contact.account_id IS DISTINCT FROM p_account_id
      OR v_uid IS NULL
      OR (
        v_action = 'zalo_message_friend'
        AND v_contact.is_friend IS DISTINCT FROM true
      )
    THEN
      RETURN NULL;
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_person';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action = 'zalo_message_group' THEN
    IF v_platform <> 'zalo'
      OR v_contact_type <> 'group'
      OR v_contact.account_id IS DISTINCT FROM p_account_id
      OR v_contact.is_joined IS DISTINCT FROM true
    THEN
      RETURN NULL;
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_group';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action = 'zalo_add_group_member' THEN
    IF v_phone IS NOT NULL THEN
      v_target_value := v_phone;
      v_target_kind := 'phone';
      v_scope := 'portable';
    ELSIF v_platform = 'zalo'
      AND v_contact_type = 'person'
      AND v_uid IS NOT NULL
      AND v_contact.account_id IS NOT DISTINCT FROM p_account_id
    THEN
      v_target_value := v_uid;
      v_target_kind := 'zalo_person';
      v_scope := 'bound:' || p_account_id::text;
    ELSE
      RETURN NULL;
    END IF;
  ELSE
    RETURN NULL;
  END IF;

  IF NULLIF(v_target_value, '') IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_target_kind LIKE 'facebook_%' THEN
    v_identity_value := COALESCE(
      NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_uid), ''),
      NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_url), ''),
      NULLIF(
        public.aka_agent_internal_normalize_facebook_identity(v_target_value),
        ''
      )
    );
  ELSIF v_target_kind = 'email' THEN
    v_identity_value := lower(v_target_value);
  ELSE
    v_identity_value := v_target_value;
  END IF;
  IF NULLIF(v_identity_value, '') IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN v_scope || ':' || v_target_kind || ':' || v_identity_value;
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_internal_route_data_group_member_v186_internal(p_source_id bigint, p_membership_id bigint, p_batch_id bigint, p_group_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_member public.auto_account_contact_group_members%ROWTYPE;
  v_contact public.auto_account_contacts%ROWTYPE;
  v_account public.auto_accounts%ROWTYPE;
  v_action text;
  v_platform text;
  v_contact_type text;
  v_name text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_input_uid text;
  v_input_phone text;
  v_input_email text;
  v_target_value text;
  v_identity_value text;
  v_uid_identity text;
  v_url_identity text;
  v_allow_alias_resolution boolean := false;
  v_target_kind text;
  v_scope text;
  v_candidate_key text;
  v_canonical_key text;
  v_aliases text[] := '{}'::text[];
  v_mapped_keys text[] := '{}'::text[];
  v_payload jsonb;
  v_input_id bigint;
  v_inserted boolean := false;
  v_info1 text;
  v_info2 text;
  v_info3 text;
  v_info4 text;
  v_info5 text;
  v_phone_carrier text;
BEGIN
  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = p_source_id;
  IF NOT FOUND OR v_source.status NOT IN ('baselining', 'active') THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'source_stopped');
  END IF;

  SELECT * INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = v_source.campaign_id
  FOR UPDATE;
  IF FOUND AND v_campaign.data_target_source_mode = 'data_group'
    AND (
      COALESCE(v_campaign.is_delete, false)
      OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now())
    )
  THEN
    EXECUTE 'SELECT public.aka_agent_finalize_data_group_campaign($1, $2, $3, $4)'
    USING v_source.staff_id, v_source.organization_id, v_campaign.id,
      CASE WHEN COALESCE(v_campaign.is_delete, false)
        THEN 'Chiến dịch đã bị xoá' ELSE 'Chiến dịch đã hết hạn' END;
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'campaign_hard_ended');
  END IF;
  IF NOT FOUND
    OR v_campaign.staff_id IS DISTINCT FROM v_source.staff_id
    OR v_campaign.organization_id IS DISTINCT FROM v_source.organization_id
    OR COALESCE(v_campaign.is_delete, false)
    OR v_campaign.data_target_source_mode <> 'data_group'
    OR v_campaign.data_group_id IS DISTINCT FROM v_source.group_id
    OR v_campaign.status NOT IN ('chờ xử lý', 'tạm dừng', 'đang chạy')
    OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now())
  THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'campaign_terminal');
  END IF;

  SELECT * INTO v_member
  FROM public.auto_account_contact_group_members AS member
  WHERE member.id = p_membership_id
    AND member.group_id = v_source.group_id
    AND member.is_delete = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'membership_inactive');
  END IF;

  SELECT * INTO v_contact
  FROM public.auto_account_contacts AS contact
  WHERE contact.id = v_member.contact_id
    AND private.shared_data_member_owner(v_source.group_id,contact.staff_id,v_source.staff_id,v_source.organization_id)
    AND contact.organization_id = v_source.organization_id
    AND COALESCE(contact.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'contact_inactive');
  END IF;

  SELECT * INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = v_campaign.account_id
    AND account.staff_id = v_source.staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_source.organization_id)
    AND COALESCE(account.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'campaign_account_inactive');
  END IF;

  v_action := btrim(COALESCE(v_campaign.action_id, ''));
  v_platform := lower(btrim(COALESCE(v_contact.flatform_type, '')));
  v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
  v_name := NULLIF(btrim(COALESCE(v_contact.name, '')), '');
  v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
  v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
  v_phone := public.aka_agent_internal_normalize_phone(COALESCE(
    NULLIF(v_contact.phone, ''), NULLIF(v_contact.extra_data ->> 'phone', ''),
    CASE WHEN v_contact_type = 'phone' THEN v_contact.uid ELSE NULL END, ''
  ));
  v_phone := NULLIF(v_phone, '');
  v_email := NULLIF(lower(btrim(COALESCE(
    NULLIF(v_contact.email, ''), NULLIF(v_contact.extra_data ->> 'email', ''),
    CASE WHEN v_contact_type = 'email' THEN v_contact.uid ELSE NULL END, ''
  ))), '');
  IF v_email IS NOT NULL AND (v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
      OR length(v_email) > 254) THEN
    v_email := NULL;
  END IF;
  v_info1 := NULLIF(v_contact.extra_data ->> 'info1', '');
  v_info2 := NULLIF(v_contact.extra_data ->> 'info2', '');
  v_info3 := NULLIF(v_contact.extra_data ->> 'info3', '');
  v_info4 := NULLIF(v_contact.extra_data ->> 'info4', '');
  v_info5 := NULLIF(v_contact.extra_data ->> 'info5', '');
  v_phone_carrier := COALESCE(
    NULLIF(v_contact.extra_data ->> 'phoneCarrier', ''),
    NULLIF(v_contact.extra_data ->> 'phone_carrier', '')
  );

  -- Portable Facebook routes.
  IF v_action IN ('facebook_group_post', 'facebook_join_group', 'facebook_find_data_group') THEN
    -- v227: Facebook routes use semantic type plus UID/URL only.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_group';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'facebook_message_uid' THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'facebook_find_data_search' THEN
    v_target_value := v_uid;
    v_target_kind := 'facebook_search';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action IN ('facebook_comment_seeding', 'facebook_comment_seeding_post') THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := CASE WHEN v_action = 'facebook_comment_seeding_post'
      THEN 'facebook_post' ELSE 'facebook_comment_target' END;
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'zalo_message_phone' THEN
    IF v_phone IS NULL THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'valid_phone_required');
    END IF;
    v_target_value := v_phone;
    v_target_kind := 'phone';
    v_scope := 'portable';
    v_input_phone := v_target_value;
  ELSIF v_action = 'zalo_join_group_link' THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'group' THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'zalo_group_required');
    END IF;
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'zalo_group_link';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'email_send' THEN
    IF v_email IS NULL THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'valid_email_required');
    END IF;
    v_target_value := v_email;
    v_target_kind := 'email';
    v_scope := 'portable';
    v_input_email := v_target_value;

  -- Account-bound routes.
  ELSIF v_action IN ('facebook_message_friend', 'facebook_group_invite') THEN
    -- v226: Facebook UID/URL targets are portable across source accounts.
    -- is_friend and contact.account_id are scan metadata only.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    -- Retain the legacy per-campaign key namespace so existing active inputs
    -- are not duplicated when this migration is applied mid-campaign.
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;
  ELSIF v_action = 'facebook_page_post' THEN
    -- v226: Page ID/URL validity is sufficient; source account is not binding.
    v_target_value := COALESCE(v_uid, v_url);
    v_target_kind := 'facebook_page';
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;
  ELSIF v_action IN (
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer'
  ) THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'person'
      OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'bound_zalo_person_required');
    END IF;
    IF v_action = 'zalo_message_friend' AND v_contact.is_friend IS DISTINCT FROM true THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'bound_zalo_friend_required');
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_person';
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;
  ELSIF v_action = 'zalo_message_group' THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'group'
      OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id
      OR v_contact.is_joined IS DISTINCT FROM true THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'bound_joined_zalo_group_required');
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_group';
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;

  -- Hybrid: a valid phone is portable and must force uid=''; UID-only remains
  -- account-bound so one account's Zalo identity is never used by another.
  ELSIF v_action = 'zalo_add_group_member' THEN
    IF v_phone IS NOT NULL THEN
      v_target_value := v_phone;
      v_target_kind := 'phone';
      v_scope := 'portable';
      v_input_phone := v_phone;
      v_input_uid := '';
    ELSIF v_platform = 'zalo' AND v_contact_type = 'person'
      AND v_uid IS NOT NULL
      AND v_contact.account_id IS NOT DISTINCT FROM v_campaign.account_id THEN
      v_target_value := v_uid;
      v_target_kind := 'zalo_person';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_uid;
    ELSE
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'hybrid_target_not_routable');
    END IF;
  ELSE
    -- Includes SMS, voice, Zalo realtime, cancel-request and every future action
    -- until its delivery contract is explicitly added here.
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'unsupported_action');
  END IF;

  IF NULLIF(v_target_value, '') IS NULL THEN
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'target_value_missing');
  END IF;

  -- Canonicalization is action-aware.  Phone/email routes intentionally carry
  -- no unrelated UID/URL aliases; doing so could merge two different people
  -- merely because an imported row happened to contain extra columns.
  IF v_target_kind LIKE 'facebook_%' THEN
    v_uid_identity := CASE WHEN v_uid IS NULL THEN NULL
      ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_uid), '') END;
    v_url_identity := CASE WHEN v_url IS NULL THEN NULL
      ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_url), '') END;
    v_identity_value := COALESCE(
      v_uid_identity,
      v_url_identity,
      NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_target_value), '')
    );
    -- UID and URL stored on the same Facebook contact are explicit aliases for
    -- that row. Canonical identity prefers UID while input.uid keeps the raw
    -- URL/value required by the runtime.
    v_allow_alias_resolution := true;
  ELSIF v_target_kind = 'email' THEN
    v_identity_value := lower(v_target_value);
  ELSE
    v_identity_value := v_target_value;
  END IF;
  IF NULLIF(v_identity_value, '') IS NULL THEN
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'canonical_identity_missing');
  END IF;
  v_candidate_key := v_scope || ':' || v_target_kind || ':' || v_identity_value;
  v_aliases := array_append(v_aliases, v_candidate_key);
  IF v_target_kind LIKE 'facebook_%' AND v_uid_identity IS NOT NULL THEN
    v_aliases := array_append(
      v_aliases, v_scope || ':' || v_target_kind || ':' || v_uid_identity
    );
  END IF;
  IF v_target_kind LIKE 'facebook_%' AND v_url_identity IS NOT NULL THEN
    v_aliases := array_append(
      v_aliases, v_scope || ':' || v_target_kind || ':' || v_url_identity
    );
  END IF;
  SELECT COALESCE(array_agg(DISTINCT alias.canonical_target_key), '{}'::text[])
  INTO v_mapped_keys
  FROM public.auto_campaign_input_target_aliases AS alias
  WHERE alias.campaign_id = v_campaign.id AND alias.alias_key = ANY(v_aliases);

  IF cardinality(v_mapped_keys) > 1
    OR (
      cardinality(v_mapped_keys) = 1
      AND NOT v_allow_alias_resolution
      AND v_mapped_keys[1] IS DISTINCT FROM v_candidate_key
    )
  THEN
    UPDATE public.auto_campaign_input_target_aliases AS alias
    SET conflict_count = alias.conflict_count + 1,
        last_conflict_at = now(),
        last_conflict_payload = jsonb_build_object(
          'membershipId', v_member.id,
          'candidateCanonicalKey', v_candidate_key,
          'mappedCanonicalKeys', to_jsonb(v_mapped_keys),
          'aliases', to_jsonb(v_aliases)
        ),
        updated_at = now()
    WHERE alias.campaign_id = v_campaign.id AND alias.alias_key = ANY(v_aliases);
    RETURN jsonb_build_object(
      'status', 'conflict', 'reason', 'canonical_alias_conflict',
      'aliases', to_jsonb(v_aliases), 'canonicalKeys', to_jsonb(v_mapped_keys)
    );
  END IF;
  -- One established Facebook alias may resolve a UID-only or URL-only row.
  -- All other actions require exact candidate agreement.
  v_canonical_key := CASE
    WHEN v_allow_alias_resolution AND cardinality(v_mapped_keys) = 1
      THEN v_mapped_keys[1]
    ELSE v_candidate_key
  END;

  v_payload := jsonb_strip_nulls(jsonb_build_object(
    'name', COALESCE(v_name, v_target_value),
    'phone', v_input_phone,
    'phone_carrier', v_phone_carrier,
    'uid', v_input_uid,
    'email', v_input_email,
    'info1', v_info1, 'info2', v_info2, 'info3', v_info3,
    'info4', v_info4, 'info5', v_info5,
    'contact_id', v_contact.id,
    'membership_id', v_member.id,
    'source_account_id', v_contact.account_id,
    'contact_type', v_contact.contact_type,
    'flatform_type', v_contact.flatform_type,
    'canonical_target_key', v_canonical_key
  ));

  INSERT INTO public.auto_campaign_input_data (
    campaign_id, input_id, name, phone, phone_carrier, uid, email,
    info1, info2, info3, info4, info5, status, schedule, is_delete,
    canonical_target_key, created_at
  ) VALUES (
    v_campaign.id, NULL, COALESCE(v_name, v_target_value),
    v_input_phone, v_phone_carrier, v_input_uid, v_input_email,
    v_info1, v_info2, v_info3, v_info4, v_info5,
    'chờ xử lý', COALESCE(v_campaign.schedule, now()), false,
    v_canonical_key, now()
  )
  ON CONFLICT (campaign_id, canonical_target_key)
    WHERE canonical_target_key IS NOT NULL AND COALESCE(is_delete, false) = false
  DO NOTHING
  RETURNING id INTO v_input_id;

  IF v_input_id IS NULL THEN
    SELECT input_data.id INTO v_input_id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = v_campaign.id
      AND input_data.canonical_target_key = v_canonical_key
      AND COALESCE(input_data.is_delete, false) = false
    FOR UPDATE;
  ELSE
    v_inserted := true;
  END IF;

  INSERT INTO public.auto_campaign_input_target_aliases (
    campaign_id, alias_key, canonical_target_key, input_data_id
  )
  SELECT v_campaign.id, candidate.alias_key, v_canonical_key, v_input_id
  FROM (SELECT DISTINCT unnest(v_aliases) AS alias_key) AS candidate
  ON CONFLICT (campaign_id, alias_key) DO UPDATE
  SET input_data_id = EXCLUDED.input_data_id,
      updated_at = now()
  WHERE auto_campaign_input_target_aliases.canonical_target_key = EXCLUDED.canonical_target_key;

  INSERT INTO public.auto_campaign_input_origins (
    input_data_id, source_id, group_id, membership_id, batch_id,
    group_revision, canonical_target_key, payload_snapshot
  ) VALUES (
    v_input_id, v_source.id, v_source.group_id, v_member.id, p_batch_id,
    p_group_revision, v_canonical_key, v_payload
  ) ON CONFLICT DO NOTHING;

  UPDATE public.auto_campaign_data_group_sources
  SET last_ingest_at = now(), updated_at = now()
  WHERE id = v_source.id;

  UPDATE public.auto_campaigns
  SET note = NULL, updated_at = now()
  WHERE id = v_campaign.id
    AND note IN ('Chờ data phù hợp', 'Chờ data mới');

  RETURN jsonb_build_object(
    'status', CASE WHEN v_inserted THEN 'inserted' ELSE 'existing' END,
    'inputDataId', v_input_id,
    'canonicalTargetKey', v_canonical_key
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.aka_agent_internal_route_data_group_member(p_source_id bigint, p_membership_id bigint, p_batch_id bigint, p_group_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_campaign_id bigint;
  v_action_id text;
  v_group_id bigint;
  v_staff_id bigint;
  v_organization_id bigint;
  v_campaign_is_delete boolean;
  v_campaign_schedule_end_date timestamptz;
BEGIN
  -- V409: serialize against sharing edits before joining the existing campaign barrier.
  SELECT group_id,staff_id,organization_id INTO v_group_id,v_staff_id,v_organization_id
    FROM public.auto_campaign_data_group_sources WHERE id=p_source_id;
  IF v_group_id IS NOT NULL AND NOT private.lock_read_data_group(v_group_id,v_staff_id,v_organization_id) THEN
    SELECT campaign_id INTO v_campaign_id FROM public.auto_campaign_data_group_sources WHERE id=p_source_id;
    PERFORM public.aka_agent_lock_campaign_input_serialization(v_campaign_id);
    UPDATE public.auto_campaign_data_group_sources SET status='stopped',stop_reason='sharing_revoked',stopped_at=now(),updated_at=now()
      WHERE id=p_source_id AND status IN ('active','baselining');
    RETURN jsonb_build_object('status','no_intake','reason','sharing_revoked');
  END IF;
  SELECT
    campaign.id,
    campaign.action_id,
    source.group_id,
    campaign.staff_id,
    campaign.organization_id
  INTO
    v_campaign_id,
    v_action_id,
    v_group_id,
    v_staff_id,
    v_organization_id
  FROM public.auto_campaign_data_group_sources AS source
  JOIN public.auto_campaigns AS campaign
    ON campaign.id = source.campaign_id
  WHERE source.id = p_source_id;

  IF v_campaign_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.auto_account_contact_group_members AS member
      WHERE member.id = p_membership_id
        AND member.group_id = v_group_id
    )
    AND NOT (
      -- v228: valid-phone routes ignore semantic/platform/contact/account and
      -- relationship metadata. UID-only add-member routing does not enter here.
      v_action_id IN ('zalo_message_phone', 'zalo_add_group_member')
      AND public.aka_agent_data_group_membership_has_valid_phone(
        p_membership_id, v_group_id
      )
    )
    AND NOT public.aka_agent_data_group_membership_semantic_compatible(
      p_membership_id, v_action_id, v_group_id
    )
  THEN
    RETURN jsonb_build_object(
      'status', 'incompatible',
      'reason', 'data_group_member_semantic_type_mismatch'
    );
  END IF;

  IF v_campaign_id IS NOT NULL THEN
    PERFORM public.aka_agent_lock_campaign_input_serialization(v_campaign_id);

    SELECT
      COALESCE(campaign.is_delete, false),
      campaign.schedule_end_date
    INTO
      v_campaign_is_delete,
      v_campaign_schedule_end_date
    FROM public.auto_campaigns AS campaign
    WHERE campaign.id = v_campaign_id
      AND campaign.staff_id = v_staff_id
      AND campaign.organization_id = v_organization_id
      AND campaign.data_target_source_mode = 'data_group'
    FOR UPDATE OF campaign;

    IF FOUND AND (
      v_campaign_is_delete
      OR (
        v_campaign_schedule_end_date IS NOT NULL
        AND v_campaign_schedule_end_date <= now()
      )
    ) THEN
      PERFORM public.aka_agent_internal_finalize_data_group_campaign_v219(
        v_staff_id,
        v_organization_id,
        v_campaign_id,
        CASE
          WHEN v_campaign_is_delete THEN 'Chiến dịch đã bị xoá'
          ELSE 'Chiến dịch đã hết hạn'
        END
      );
      RETURN jsonb_build_object(
        'status', 'no_intake', 'reason', 'campaign_hard_ended'
      );
    END IF;
  END IF;

  RETURN public.aka_agent_internal_route_data_group_member_v205_internal(
    p_source_id, p_membership_id, p_batch_id, p_group_revision
  );
END;
$function$;


CREATE FUNCTION private.copy_shared_group(p_staff_id bigint,p_organization_id bigint,p_kind text,p_group_id bigint,p_data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE
  v_request text:=p_data->>'requestId';
  v_hash text:=md5(p_data::text);
  v_prior private.group_copy_requests%ROWTYPE;
  v_access jsonb;
  v_source public.auto_account_contact_groups%ROWTYPE;
  v_target public.auto_account_contact_groups%ROWTYPE;
  v_content_group public.auto_content_groups%ROWTYPE;
  v_target_id bigint:=NULLIF(p_data->>'targetGroupId','')::bigint;
  v_template_id bigint:=NULLIF(p_data->>'templateId','')::bigint;
  v_member_ids bigint[];
  v_contact_id bigint;
  v_member_id bigint;
  v_count integer:=0;
  v_row record;
  v_revision bigint;
  v_result jsonb;
  v_base_name text;
  v_copy_name text;
  v_name_attempt integer;
  v_inserted_template_id bigint;
BEGIN
  IF v_request IS NULL OR length(v_request) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'invalid_group_copy_request'; END IF;
  IF p_kind='data' THEN
    PERFORM id FROM public.auto_account_contact_groups WHERE id IN (p_group_id,v_target_id) ORDER BY id FOR UPDATE;
  ELSE
    -- Copies into the same staff library allocate names in one transaction.
    -- Take this before group locks so overlapping multi-template copies cannot
    -- wait on each other's unique names in opposite source-template orders.
    PERFORM pg_advisory_xact_lock(hashtextextended('group-sharing-content-copy:'||p_staff_id::text,0));
    PERFORM id FROM public.auto_content_groups WHERE id IN (p_group_id,v_target_id) ORDER BY id FOR UPDATE;
  END IF;
  v_access:=private.group_access(p_kind,p_group_id,p_staff_id,p_organization_id);
  IF v_access IS NULL THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;
  IF v_target_id IS NOT NULL AND NOT COALESCE((private.group_access(p_kind,v_target_id,p_staff_id,p_organization_id)->>'canManage')::boolean,false)
    THEN RAISE EXCEPTION 'group_sharing_owner_required'; END IF;
  IF v_target_id=p_group_id THEN RAISE EXCEPTION 'invalid_group_copy_target'; END IF;
  INSERT INTO private.group_copy_requests(staff_id,organization_id,request_id,request_hash)
    VALUES(p_staff_id,p_organization_id,v_request,v_hash) ON CONFLICT DO NOTHING;
  SELECT * INTO v_prior FROM private.group_copy_requests WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND request_id=v_request FOR UPDATE;
  IF v_prior.request_hash<>v_hash THEN RAISE EXCEPTION 'data_group_request_id_conflict'; END IF;
  IF v_prior.result IS NOT NULL THEN RETURN v_prior.result; END IF;
  IF p_kind='data' THEN
    SELECT * INTO v_source FROM public.auto_account_contact_groups WHERE id=p_group_id;
    IF v_target_id IS NULL THEN
      INSERT INTO public.auto_account_contact_groups(name,color,sort_order,purpose,staff_id,organization_id,data_type_category_item_id,dataset_sync_mode,is_delete)
        VALUES(COALESCE(NULLIF(btrim(p_data->>'name'),''),v_source.name||' - Bản sao'),v_source.color,0,'data_group',p_staff_id,p_organization_id,v_source.data_type_category_item_id,'manual',false)
        RETURNING id INTO v_target_id;
    END IF;
    SELECT * INTO v_target FROM public.auto_account_contact_groups WHERE id=v_target_id;
    IF v_target.bound_zalo_account_id IS NOT NULL THEN RAISE EXCEPTION 'data_group_bound_source_unknown'; END IF;
    IF v_target.data_type_category_item_id IS NOT NULL AND v_target.data_type_category_item_id IS DISTINCT FROM v_source.data_type_category_item_id
      THEN RAISE EXCEPTION 'data_group_ingest_semantic_type_mismatch'; END IF;
    IF jsonb_typeof(p_data->'membershipIds')='array' THEN
      SELECT COALESCE(array_agg(DISTINCT x::bigint),'{}'::bigint[]) INTO v_member_ids FROM jsonb_array_elements_text(p_data->'membershipIds') x;
      IF EXISTS(SELECT 1 FROM unnest(v_member_ids) requested(id) WHERE NOT EXISTS(
        SELECT 1 FROM public.auto_account_contact_group_members m JOIN public.auto_account_contacts c ON c.id=m.contact_id
        WHERE m.id=requested.id AND m.group_id=p_group_id AND NOT m.is_delete AND NOT COALESCE(c.is_delete,false)
          AND c.staff_id=v_source.staff_id AND c.organization_id=p_organization_id))
        THEN RAISE EXCEPTION 'invalid_group_copy_members'; END IF;
    END IF;
    UPDATE public.auto_account_contact_groups SET revision=revision+1 WHERE id=v_target_id RETURNING revision INTO v_revision;
    FOR v_row IN SELECT c.*,COALESCE(o.data_type_category_item_id,v_source.data_type_category_item_id) copied_type
      FROM public.auto_account_contact_group_members m JOIN public.auto_account_contacts c ON c.id=m.contact_id
      LEFT JOIN public.auto_account_contact_group_member_origins o ON o.id=m.primary_origin_id AND o.is_current
      WHERE m.group_id=p_group_id AND NOT m.is_delete AND NOT COALESCE(c.is_delete,false)
        AND c.staff_id=v_source.staff_id AND c.organization_id=p_organization_id
        AND (v_member_ids IS NULL OR m.id=ANY(v_member_ids)) ORDER BY m.id
    LOOP
      -- Independent accountless records: never copy account permissions, tags, relationship flags or raw extra_data.
      INSERT INTO public.auto_account_contacts(staff_id,organization_id,account_id,contact_type,flatform_type,name,uid,url,phone,email,extra_data,is_delete)
        VALUES(p_staff_id,p_organization_id,NULL,v_row.contact_type,v_row.flatform_type,v_row.name,v_row.uid,v_row.url,v_row.phone,v_row.email,
          jsonb_strip_nulls(jsonb_build_object('info1',v_row.extra_data->'info1','info2',v_row.extra_data->'info2',
            'info3',v_row.extra_data->'info3','info4',v_row.extra_data->'info4','info5',v_row.extra_data->'info5')),false)
        RETURNING id INTO v_contact_id;
      INSERT INTO public.auto_account_contact_group_members(group_id,contact_id,change_revision,is_delete)
        VALUES(v_target_id,v_contact_id,v_revision,false) RETURNING id INTO v_member_id;
      INSERT INTO public.auto_account_contact_group_member_origins(membership_id,kind,source_name_snapshot,data_type_category_item_id,is_current)
        VALUES(v_member_id,'manual','Bản sao: '||v_source.name,v_row.copied_type,true);
      -- Preserve normal intake for the recipient's existing target group.
      FOR v_result IN SELECT public.aka_agent_internal_route_data_group_member(s.id,v_member_id,NULL,v_revision)
        FROM public.auto_campaign_data_group_sources s WHERE s.group_id=v_target_id AND s.status IN ('active','baselining') ORDER BY s.campaign_id
      LOOP NULL; END LOOP;
      v_count:=v_count+1;
    END LOOP;
  ELSE
    SELECT * INTO v_content_group FROM public.auto_content_groups WHERE id=p_group_id;
    IF NOT v_content_group.is_active AND (v_access->>'role')='shared' THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;
    IF v_template_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.auto_content_templates
      WHERE id=v_template_id AND group_id=p_group_id AND staff_id=v_content_group.staff_id AND organization_id=p_organization_id AND NOT is_delete)
      THEN RAISE EXCEPTION 'invalid_group_copy_template'; END IF;
    IF v_target_id IS NULL THEN
      v_base_name:=COALESCE(NULLIF(btrim(p_data->>'name'),''),v_content_group.name||' - Bản sao');
      v_copy_name:=v_base_name;
      v_name_attempt:=1;
      LOOP
        -- Let the existing unique index arbitrate concurrent copies/ordinary
        -- creates as well as case-insensitive, trimmed-name collisions.
        INSERT INTO public.auto_content_groups(name,description,stt,is_active,staff_id,organization_id,is_delete)
          VALUES(v_copy_name,v_content_group.description,100,true,p_staff_id,p_organization_id,false)
          ON CONFLICT (staff_id, (lower(btrim(name)))) WHERE staff_id IS NOT NULL AND is_delete=false
          DO NOTHING RETURNING id INTO v_target_id;
        EXIT WHEN v_target_id IS NOT NULL;
        v_name_attempt:=v_name_attempt+1;
        v_copy_name:=v_base_name||' ('||v_name_attempt||')';
      END LOOP;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.auto_content_groups WHERE id=v_target_id AND is_active) THEN RAISE EXCEPTION 'invalid_group_copy_target'; END IF;
    FOR v_row IN SELECT * FROM public.auto_content_templates
      WHERE group_id=p_group_id AND staff_id=v_content_group.staff_id AND organization_id=p_organization_id
        AND NOT is_delete AND (v_template_id IS NULL OR id=v_template_id) ORDER BY id
    LOOP
      v_copy_name:=v_row.name;
      v_base_name:=v_row.name||' - Bản sao';
      v_name_attempt:=0;
      LOOP
        INSERT INTO public.auto_content_templates(name,content,group_id,content_type_id,image_urls,channels,channel_image_urls,base_content_html,staff_id,organization_id,is_delete)
          VALUES(v_copy_name,v_row.content,v_target_id,v_row.content_type_id,v_row.image_urls,v_row.channels,v_row.channel_image_urls,v_row.base_content_html,p_staff_id,p_organization_id,false)
          ON CONFLICT (staff_id, (lower(btrim(name)))) WHERE is_delete=false
          DO NOTHING RETURNING id INTO v_inserted_template_id;
        EXIT WHEN v_inserted_template_id IS NOT NULL;
        v_name_attempt:=v_name_attempt+1;
        v_copy_name:=v_base_name||CASE WHEN v_name_attempt=1 THEN '' ELSE ' ('||v_name_attempt||')' END;
      END LOOP;
      v_count:=v_count+1;
    END LOOP;
  END IF;
  v_result:=jsonb_build_object('groupId',v_target_id,'count',v_count);
  UPDATE private.group_copy_requests SET result=v_result WHERE staff_id=p_staff_id AND organization_id=p_organization_id AND request_id=v_request;
  RETURN v_result;
END;
$fn$;
REVOKE ALL ON FUNCTION private.copy_shared_group(bigint,bigint,text,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;


CREATE FUNCTION public.aka_agent_group_sharing(
  p_staff_id bigint,p_organization_id bigint,p_auth_username text,p_auth_password text,
  p_action text,p_data jsonb DEFAULT '{}'::jsonb
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,public SET statement_timeout='60s' AS $fn$
DECLARE
  v_kind text := p_data->>'kind';
  v_id bigint := NULLIF(p_data->>'groupId','')::bigint;
  v_access jsonb;
  v_scope text;
  v_revision bigint;
  v_recipients bigint[];
  v_owner bigint;
  v_result jsonb;
  v_row record;
  v_ids bigint[];
  v_template_id bigint;
BEGIN
  PERFORM public.auto_assert_automation_identity(p_staff_id,p_organization_id,p_auth_username,p_auth_password);
  IF NOT EXISTS(SELECT 1 FROM public.org_staff WHERE id=p_staff_id AND organization_id=p_organization_id
    AND is_active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;

  IF p_action='staff' THEN
    RETURN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',s.id,'name',COALESCE(NULLIF(s.name,''),'Nhân viên #'||s.id)) ORDER BY s.name,s.id),'[]'::jsonb)
      FROM public.org_staff s WHERE s.organization_id=p_organization_id AND s.deleted_at IS NULL AND s.is_active AND s.id<>p_staff_id);
  ELSIF p_action='data_groups' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(g)||jsonb_build_object(
      'access',private.group_access('data',g.id,p_staff_id,p_organization_id),
      'bound_zalo_account_id',cg.bound_zalo_account_id,
      'bound_zalo_account_name',CASE WHEN cg.staff_id=p_staff_id THEN a.name END)),'[]'::jsonb)
    INTO v_result FROM private.list_shared_data_groups(
      p_staff_id,p_organization_id,p_data->>'search',p_data->>'compatibleActionId',
      (p_data->>'compatibleDataTypeCategoryItemId')::bigint,
      CASE WHEN jsonb_typeof(p_data->'dataTypeCategoryItemIds')='array' AND jsonb_array_length(p_data->'dataTypeCategoryItemIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'dataTypeCategoryItemIds')::bigint) END,
      COALESCE((p_data->>'offset')::integer,0),LEAST(500,COALESCE((p_data->>'limit')::integer,50)),
      COALESCE((p_data->>'unrestrictedOnly')::boolean,false),COALESCE((p_data->>'ownedOnly')::boolean,false)
    ) g JOIN public.auto_account_contact_groups cg ON cg.id=g.id LEFT JOIN public.auto_accounts a ON a.id=cg.bound_zalo_account_id;
    RETURN v_result;
  ELSIF p_action='content_groups' THEN
    RETURN (SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'id')::bigint),'[]'::jsonb) FROM (
      SELECT to_jsonb(g)||jsonb_build_object('access',private.group_access('content',g.id,p_staff_id,p_organization_id)) row_data
      FROM public.auto_content_groups g WHERE g.organization_id=p_organization_id AND NOT g.is_delete
        AND g.id>COALESCE((p_data->>'afterId')::bigint,0)
        AND private.group_access('content',g.id,p_staff_id,p_organization_id) IS NOT NULL
        AND (NOT COALESCE((p_data->>'ownedOnly')::boolean,false) OR g.staff_id=p_staff_id)
      ORDER BY g.id LIMIT 500
    ) page);
  ELSIF p_action='content_templates' THEN
    RETURN (SELECT COALESCE(jsonb_agg(row_data ORDER BY (row_data->>'id')::bigint),'[]'::jsonb) FROM (
      SELECT to_jsonb(t)||jsonb_build_object('content_group',jsonb_build_object('name',g.name),
        'access',CASE WHEN t.staff_id=p_staff_id THEN jsonb_build_object('role','owner','ownerStaffId',p_staff_id,'canManage',true,'canUse',true,'canCopy',true)
          ELSE private.group_access('content',g.id,p_staff_id,p_organization_id) END) row_data
      FROM public.auto_content_templates t LEFT JOIN public.auto_content_groups g ON g.id=t.group_id
      WHERE t.organization_id=p_organization_id AND NOT t.is_delete
        AND t.id>COALESCE((p_data->>'afterId')::bigint,0)
        AND (t.staff_id=p_staff_id OR (g.staff_id=t.staff_id AND g.organization_id=t.organization_id
          AND g.is_active AND private.group_access('content',g.id,p_staff_id,p_organization_id) IS NOT NULL))
      ORDER BY t.id LIMIT 500
    ) page);
  END IF;

  IF v_kind NOT IN ('data','content') OR v_kind IS NULL OR v_id IS NULL THEN
    RAISE EXCEPTION 'invalid_group_sharing_request';
  END IF;
  -- Lock writes/copies with the source group; all affected destinations are locked in ID order by copy RPC.
  IF p_action='save' THEN
    IF v_kind='data' THEN PERFORM id FROM public.auto_account_contact_groups WHERE id=v_id FOR UPDATE;
    ELSE PERFORM id FROM public.auto_content_groups WHERE id=v_id FOR UPDATE; END IF;
  END IF;
  v_access:=private.group_access(v_kind,v_id,p_staff_id,p_organization_id);
  IF v_access IS NULL THEN RAISE EXCEPTION 'group_sharing_access_denied'; END IF;
  v_owner:=(v_access->>'ownerStaffId')::bigint;

  IF p_action IN ('get','save') THEN
    IF NOT (v_access->>'canManage')::boolean THEN
      IF p_action='save' THEN RAISE EXCEPTION 'group_sharing_owner_required'; END IF;
      RETURN jsonb_build_object('scope',v_access->>'scope','revision',v_access->>'revision','recipientIds','[]'::jsonb,'access',v_access);
    END IF;
    IF p_action='save' THEN
      v_scope:=p_data->>'scope';
      IF v_scope IS NULL OR v_scope NOT IN ('private','organization','selected') THEN RAISE EXCEPTION 'invalid_group_sharing_scope'; END IF;
      IF p_data->>'expectedRevision' IS DISTINCT FROM v_access->>'revision' THEN RAISE EXCEPTION 'group_sharing_conflict'; END IF;
      IF jsonb_typeof(p_data->'recipientIds') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid_group_sharing_recipients'; END IF;
      SELECT COALESCE(array_agg(DISTINCT x::bigint),'{}'::bigint[]) INTO v_recipients FROM jsonb_array_elements_text(p_data->'recipientIds') x;
      IF v_scope<>'selected' THEN v_recipients:='{}'::bigint[]; END IF;
      IF v_scope='selected' AND cardinality(v_recipients)=0 THEN RAISE EXCEPTION 'group_sharing_recipients_required'; END IF;
      IF EXISTS(SELECT 1 FROM unnest(v_recipients) r(id) LEFT JOIN public.org_staff s
        ON s.id=r.id AND s.organization_id=p_organization_id AND s.deleted_at IS NULL AND s.is_active
        WHERE s.id IS NULL OR s.id=p_staff_id) THEN RAISE EXCEPTION 'invalid_group_sharing_recipients'; END IF;
      IF v_kind='data' THEN
        DELETE FROM public.auto_data_group_recipients WHERE group_id=v_id;
        INSERT INTO public.auto_data_group_recipients SELECT v_id,unnest(v_recipients);
        UPDATE public.auto_account_contact_groups SET sharing_scope=v_scope,sharing_revision=sharing_revision+1 WHERE id=v_id;
        -- No campaign pause, deletion or input reset. A new grant never reactivates stopped sources.
        FOR v_row IN SELECT source.id,source.campaign_id FROM public.auto_campaign_data_group_sources source
          WHERE source.group_id=v_id AND source.staff_id<>p_staff_id AND source.status IN ('active','baselining')
          AND NOT private.can_read_data_group(v_id,source.staff_id,source.organization_id)
          ORDER BY source.campaign_id,source.id
        LOOP
          PERFORM public.aka_agent_lock_campaign_input_serialization(v_row.campaign_id);
          UPDATE public.auto_campaign_data_group_sources SET status='stopped',stop_reason='sharing_revoked',stopped_at=now(),updated_at=now()
            WHERE id=v_row.id AND status IN ('active','baselining');
        END LOOP;
      ELSE
        DELETE FROM public.auto_content_group_recipients WHERE group_id=v_id;
        INSERT INTO public.auto_content_group_recipients SELECT v_id,unnest(v_recipients);
        UPDATE public.auto_content_groups SET sharing_scope=v_scope,sharing_revision=sharing_revision+1 WHERE id=v_id;
      END IF;
      v_access:=private.group_access(v_kind,v_id,p_staff_id,p_organization_id);
    END IF;
    IF v_kind='data' THEN SELECT COALESCE(array_agg(staff_id ORDER BY staff_id),'{}'::bigint[]) INTO v_recipients FROM public.auto_data_group_recipients WHERE group_id=v_id;
    ELSE SELECT COALESCE(array_agg(staff_id ORDER BY staff_id),'{}'::bigint[]) INTO v_recipients FROM public.auto_content_group_recipients WHERE group_id=v_id; END IF;
    RETURN jsonb_build_object('scope',v_access->>'scope','revision',v_access->>'revision','recipientIds',to_jsonb(v_recipients),'access',v_access);
  ELSIF p_action='validate_content_selection' AND v_kind='content' THEN
    PERFORM id FROM public.auto_content_groups WHERE id=v_id AND is_active FOR SHARE;
    IF NOT FOUND OR private.group_access('content',v_id,p_staff_id,p_organization_id) IS NULL THEN
      RAISE EXCEPTION 'group_sharing_access_denied';
    END IF;
    RETURN jsonb_build_object('allowed',true);
  ELSIF p_action='copy' THEN
    RETURN private.copy_shared_group(p_staff_id,p_organization_id,v_kind,v_id,p_data);
  ELSIF p_action='data_members' AND v_kind='data' THEN
    IF jsonb_typeof(p_data->'ids')='array' THEN SELECT array_agg(x::bigint) INTO v_ids FROM jsonb_array_elements_text(p_data->'ids') x; END IF;
    IF jsonb_typeof(p_data->'sourceCodes')='array' AND jsonb_array_length(p_data->'sourceCodes')>0 THEN
      IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_data->'sourceCodes') code
        WHERE code NOT IN ('upload','scan','automation','dynamic_filter','external_sync')) THEN
        RAISE EXCEPTION 'invalid_data_group_source_filter';
      END IF;
      SELECT COALESCE(array_agg(m.id),ARRAY[-1]::bigint[]) INTO v_ids
      FROM public.auto_account_contact_group_members m WHERE m.group_id=v_id AND NOT m.is_delete
        AND (v_ids IS NULL OR m.id=ANY(v_ids))
        AND EXISTS(SELECT 1 FROM public.auto_account_contact_group_member_origins o JOIN public.category_item c ON c.id=o.source_category_item_id
          WHERE o.membership_id=m.id AND o.is_current AND c.code IN (SELECT jsonb_array_elements_text(p_data->'sourceCodes')));
    END IF;
    RETURN (SELECT COALESCE(jsonb_agg(CASE WHEN v_owner=p_staff_id THEN to_jsonb(m) ELSE to_jsonb(m)||jsonb_build_object(
      'source_account_name',NULL,'source_automation_id',NULL,'source_automation_name',NULL,
      'dataset_ids','[]'::jsonb,'dataset_names','[]'::jsonb,'provenance','[]'::jsonb) END),'[]'::jsonb)
    FROM private.read_shared_group_members(
      v_owner,p_organization_id,v_id,p_data->>'search',
      CASE WHEN jsonb_typeof(p_data->'accountIds')='array' AND jsonb_array_length(p_data->'accountIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'accountIds')::bigint) END,
      COALESCE((p_data->>'includeAccountless')::boolean,true),
      CASE WHEN jsonb_typeof(p_data->'contactTypes')='array' AND jsonb_array_length(p_data->'contactTypes')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'contactTypes')) END,
      CASE WHEN jsonb_typeof(p_data->'flatformTypes')='array' AND jsonb_array_length(p_data->'flatformTypes')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'flatformTypes')) END,
      COALESCE(p_data->>'status','all'),
      CASE WHEN jsonb_typeof(p_data->'datasetIds')='array' AND jsonb_array_length(p_data->'datasetIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'datasetIds')::bigint) END,
      CASE WHEN jsonb_typeof(p_data->'dataTypeCategoryItemIds')='array' AND jsonb_array_length(p_data->'dataTypeCategoryItemIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'dataTypeCategoryItemIds')::bigint) END,
      v_ids,CASE WHEN jsonb_typeof(p_data->'excludeIds')='array' AND jsonb_array_length(p_data->'excludeIds')>0 THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'excludeIds')::bigint) END,
      COALESCE((p_data->>'offset')::integer,0),LEAST(1000,COALESCE((p_data->>'limit')::integer,100))) m);
  ELSIF p_action='data_datasets' AND v_kind='data' THEN
    IF v_owner<>p_staff_id THEN RETURN '[]'::jsonb; END IF;
    RETURN (SELECT COALESCE(jsonb_agg(to_jsonb(d)),'[]'::jsonb) FROM public.aka_agent_list_data_group_datasets(p_staff_id,p_organization_id,v_id) d);
  ELSIF p_action='data_panel' AND v_kind='data' THEN
    IF v_owner=p_staff_id THEN RETURN public.aka_agent_get_data_group_panel(p_staff_id,p_organization_id,v_id,p_auth_username,p_auth_password); END IF;
    RETURN (SELECT jsonb_build_object('group',jsonb_build_object('id',g.id,'name',g.name,'color',g.color,'note',g.note,
        'created_at',g.created_at,'updated_at',g.updated_at,'data_type_category_item_id',g.data_type_category_item_id,
        'bound_zalo_account_id',g.bound_zalo_account_id)||public.aka_agent_data_type_json(g.data_type_category_item_id)
        ||jsonb_build_object('creator_name',v_access->>'ownerName','access',v_access),
      'summary',jsonb_build_object('active_membership_count',(SELECT count(*) FROM public.auto_account_contact_group_members WHERE group_id=v_id AND NOT is_delete)),
      'quality','{}'::jsonb,'source_breakdown','[]'::jsonb,'data_type_breakdown','[]'::jsonb,
      'account_breakdown','[]'::jsonb,'tags','[]'::jsonb,'history','[]'::jsonb,'campaigns','[]'::jsonb)
      FROM public.auto_account_contact_groups g WHERE g.id=v_id);
  END IF;
  RAISE EXCEPTION 'invalid_group_sharing_action';
END;
$fn$;
REVOKE ALL ON FUNCTION public.aka_agent_group_sharing(bigint,bigint,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aka_agent_group_sharing(bigint,bigint,text,text,text,jsonb) TO anon,authenticated,service_role;


NOTIFY pgrst, 'reload schema'; -- New RPC/tables require API metadata refresh.
